export const DEFAULT_DQN_CONFIG: DQNConfig = {
  algorithm: 'dqn',
  learningRate: 0.0001,
  gamma: 0.99,
  entropyCoef: 0,
  valueLossCoef: 1,
  maxGradNorm: 10,
  epochs: 1,
  miniBatchSize: 32,
  bufferSize: 10000,
  explorationInitial: 1.0,
  explorationFinal: 0.01,
  explorationDecay: 10000,
  targetUpdateFreq: 100,
  doubleDQN: true,
  duelingNetwork: false,
