import type { Trajectory, RLConfig } from '../types.js';

/**
 * SARSA configuration
 */
export interface SARSAConfig extends RLConfig {
  algorithm: 'sarsa';
  explorationInitial: number;
  explorationFinal: number;
  explorationDecay: number;
