/**
 * Default SARSA configuration
 */
export const DEFAULT_SARSA_CONFIG: SARSAConfig = {
  algorithm: 'sarsa',
  learningRate: 0.1,
  gamma: 0.99,
  entropyCoef: 0,
  valueLossCoef: 1,
  maxGradNorm: 1,
  epochs: 1,
  miniBatchSize: 1,
  explorationInitial: 1.0,
  explorationFinal: 0.01,
  explorationDecay: 10000,
  maxStates: 10000,
  useExpectedSARSA: false,
  useEligibilityTraces: false,
  traceDecay: 0.9,
