      }
      return probs;
    }

    // Epsilon-greedy probabilities
    const greedyAction = this.argmax(entry.qValues);
    const exploreProb = this.epsilon / this.numActions;

    for (let a = 0; a < this.numActions; a++) {
      probs[a] = exploreProb;
