    // Track quality
    const avgQuality = sortedTrajectories.reduce((s, t) => s + t.qualityScore, 0) / sortedTrajectories.length;
    this.qualityHistory.push(avgQuality);
    if (this.qualityHistory.length > 1000) {
      this.qualityHistory = this.qualityHistory.slice(-1000);
    }

    // Compute improvement
    const recentAvg = this.qualityHistory.slice(-10).reduce((a, b) => a + b, 0) / Math.min(10, this.qualityHistory.length);
    const oldAvg = this.qualityHistory.slice(0, Math.max(1, this.qualityHistory.length - 10)).reduce((a, b) => a + b, 0) / Math.max(1, this.qualityHistory.length - 10);
    const improvementDelta = recentAvg - oldAvg;

    this.totalLearnTime += performance.now() - startTime;
    this.learnIterations++;

    return Math.max(0, improvementDelta * 2); // Scale for research mode
  }

  /**
   * Apply LoRA with rank-16 for maximum expressivity
   */
  async applyLoRA(
    input: Float32Array,
    weights?: LoRAWeights
  ): Promise<Float32Array> {
    if (!weights) {
      return input;
    }

    const output = new Float32Array(input.length);
    output.set(input);

    const rank = this.config.loraRank; // 16 for research mode

    // Apply to all modules with higher blending
    for (const module of ['q_proj', 'v_proj', 'k_proj', 'o_proj']) {
      const A = weights.A.get(module);
      const B = weights.B.get(module);

      if (A && B) {
        const adapted = this.applyLoRATransform(input, A, B, rank);
        const alpha = 0.3; // Higher blending for research
        for (let i = 0; i < output.length; i++) {
          output[i] = output[i] * (1 - alpha) + adapted[i] * alpha;
        }
      }
    }

    return output;
  }

  getStats(): Record<string, number> {
    const avgQuality = this.qualityHistory.length > 0
      ? this.qualityHistory.reduce((a, b) => a + b, 0) / this.qualityHistory.length
      : 0;

    const recentQuality = this.qualityHistory.slice(-10).reduce((a, b) => a + b, 0) / Math.min(10, this.qualityHistory.length) || 0;

    return {
      avgPatternMatchMs: this.totalPatternMatches > 0
        ? this.totalPatternTime / this.totalPatternMatches
        : 0,
      avgLearnMs: this.learnIterations > 0
        ? this.totalLearnTime / this.learnIterations
        : 0,
      avgQuality,
      recentQuality,
      qualityImprovement: recentQuality - avgQuality,
      clusterCount: this.clusterCentroids.length,
      checkpointCount: this.checkpoints.length,
      adamStep: this.adamStep,
      learnIterations: this.learnIterations,
    };
  }

  /**
   * Rebuild cluster centroids using k-means
   */
  private async rebuildClusters(patterns: Pattern[]): Promise<void> {
    if (patterns.length === 0) return;

    const k = Math.min(this.config.patternClusters, patterns.length);
    const dim = patterns[0].embedding.length;

    // Initialize centroids randomly
    this.clusterCentroids = [];
    const indices = new Set<number>();
    while (indices.size < k) {
      indices.add(Math.floor(Math.random() * patterns.length));
    }
    for (const idx of indices) {
      this.clusterCentroids.push(new Float32Array(patterns[idx].embedding));
    }

    // Run k-means iterations
    for (let iter = 0; iter < 10; iter++) {
      // Assign patterns to clusters
      const clusterAssignments: number[][] = Array.from({ length: k }, () => []);

      for (let p = 0; p < patterns.length; p++) {
        let bestCluster = 0;
        let bestSim = -1;
        for (let c = 0; c < k; c++) {
          const sim = this.cosineSimilarity(patterns[p].embedding, this.clusterCentroids[c]);
          if (sim > bestSim) {
            bestSim = sim;
            bestCluster = c;
          }
        }
        clusterAssignments[bestCluster].push(p);
        this.patternIndex.set(patterns[p].patternId, bestCluster);
      }

      // Update centroids
      for (let c = 0; c < k; c++) {
        if (clusterAssignments[c].length > 0) {
          const newCentroid = new Float32Array(dim);
          for (const p of clusterAssignments[c]) {
            for (let d = 0; d < dim; d++) {
              newCentroid[d] += patterns[p].embedding[d];
            }
          }
          for (let d = 0; d < dim; d++) {
            newCentroid[d] /= clusterAssignments[c].length;
          }
          this.clusterCentroids[c] = newCentroid;
        }
      }
    }
  }

  /**
   * Get nearest clusters to embedding
   */
  private getNearestClusters(embedding: Float32Array, n: number): number[] {
    const similarities: Array<{ cluster: number; sim: number }> = [];
    for (let c = 0; c < this.clusterCentroids.length; c++) {
      similarities.push({ cluster: c, sim: this.cosineSimilarity(embedding, this.clusterCentroids[c]) });
    }
    similarities.sort((a, b) => b.sim - a.sim);
    return similarities.slice(0, n).map(s => s.cluster);
  }

  /**
   * Compute confidence for pattern match
   */
  private computeConfidence(pattern: Pattern, similarity: number): number {
    // Combine similarity with pattern history
    const historyWeight = Math.min(pattern.usageCount / 10, 1);
    return similarity * (1 - historyWeight * 0.3) + pattern.successRate * historyWeight * 0.3;
  }

  /**
   * Create learning checkpoint
   */
  private createCheckpoint(): void {
    const state = new Map<string, Float32Array>();
    for (const [key, value] of this.adamM) {
      state.set(`m_${key}`, new Float32Array(value));
    }
    for (const [key, value] of this.adamV) {
      state.set(`v_${key}`, new Float32Array(value));
    }

    this.checkpoints.push({ iteration: this.learnIterations, state });

    // Keep only last 10 checkpoints
    if (this.checkpoints.length > 10) {
      this.checkpoints = this.checkpoints.slice(-10);
    }
  }

  /**
   * Process a mini-batch with Adam optimizer
   */
  private async processBatch(
    batch: Trajectory[],
    learningRate: number,
    ewcState: EWCState,
    ewcLambda: number
  ): Promise<number> {
    const beta1 = 0.9;
    const beta2 = 0.999;
    const epsilon = 1e-8;

    this.adamStep++;

    let totalLoss = 0;

    for (const trajectory of batch) {
      if (trajectory.steps.length === 0) continue;

      // Compute gradient from trajectory
      const gradient = this.computeTrajectoryGradient(trajectory);

      for (const [key, grad] of gradient) {
        // Get or initialize Adam state
        let m = this.adamM.get(key);
        let v = this.adamV.get(key);

        if (!m) {
          m = new Float32Array(grad.length);
          this.adamM.set(key, m);
        }
        if (!v) {
          v = new Float32Array(grad.length);
          this.adamV.set(key, v);
        }

        // Update biased first moment estimate
        for (let i = 0; i < grad.length; i++) {
          m[i] = beta1 * m[i] + (1 - beta1) * grad[i];
        }

        // Update biased second moment estimate
        for (let i = 0; i < grad.length; i++) {
          v[i] = beta2 * v[i] + (1 - beta2) * grad[i] * grad[i];
        }

        // Bias correction
        const mHat = new Float32Array(grad.length);
        const vHat = new Float32Array(grad.length);
        for (let i = 0; i < grad.length; i++) {
          mHat[i] = m[i] / (1 - Math.pow(beta1, this.adamStep));
          vHat[i] = v[i] / (1 - Math.pow(beta2, this.adamStep));
        }

        // Compute loss contribution
        for (let i = 0; i < grad.length; i++) {
          totalLoss += grad[i] * grad[i];
        }
      }
    }

    // Add EWC penalty
    const ewcPenalty = this.computeEWCLoss(ewcState, ewcLambda);
    totalLoss += ewcPenalty;

    return totalLoss / batch.length;
  }

  /**
   * Compute gradient from trajectory
   */
  private computeTrajectoryGradient(trajectory: Trajectory): Map<string, Float32Array> {
    const gradient = new Map<string, Float32Array>();

    if (trajectory.steps.length < 2) return gradient;

    // Use advantage estimation
    const rewards = trajectory.steps.map(s => s.reward);
    const advantages = this.computeAdvantages(rewards);

    for (let i = 0; i < trajectory.steps.length; i++) {
      const step = trajectory.steps[i];
      const advantage = advantages[i];

      // Policy gradient: grad = advantage * grad_log_pi
      const stateGrad = new Float32Array(step.stateAfter.length);
      for (let j = 0; j < stateGrad.length; j++) {
        stateGrad[j] = step.stateAfter[j] * advantage;
      }

      gradient.set(`step_${i}`, stateGrad);
    }

    return gradient;
  }

  /**
   * Compute advantages using GAE
   */
  private computeAdvantages(rewards: number[]): number[] {
    const gamma = 0.99;
    const lambda = 0.95;

    const advantages = new Array(rewards.length).fill(0);
    let lastGae = 0;

    for (let t = rewards.length - 1; t >= 0; t--) {
      const nextValue = t < rewards.length - 1 ? rewards[t + 1] : 0;
      const delta = rewards[t] + gamma * nextValue - rewards[t];
      lastGae = delta + gamma * lambda * lastGae;
      advantages[t] = lastGae;
    }

    // Normalize advantages
    const mean = advantages.reduce((a, b) => a + b, 0) / advantages.length;
    const std = Math.sqrt(advantages.reduce((a, b) => a + (b - mean) ** 2, 0) / advantages.length) + 1e-8;

    return advantages.map(a => (a - mean) / std);
  }

  /**
   * Compute EWC loss for continual learning
   */
  private computeEWCLoss(ewcState: EWCState, lambda: number): number {
    let loss = 0;

    for (const [key, fisher] of ewcState.fisher) {
      const means = ewcState.means.get(key);
      const current = this.adamM.get(key);

      if (means && current) {
        for (let i = 0; i < Math.min(fisher.length, means.length, current.length); i++) {
          const diff = current[i] - means[i];
          loss += fisher[i] * diff * diff;
        }
      }
    }

    return lambda * loss * 0.5;
  }
}

/**
 * Mixture of Experts (MoE) Router for Dynamic Agent Routing
 *
 * Features:
 * - 8 expert slots for specialized agent types
 * - Gating network for soft expert selection (top-k)
 * - Online weight updates via reward signals
 * - Load balancing with auxiliary loss
 * - Weight persistence to .swarm/moe-weights.json
 *
 * Architecture:
 * - Input: 384-dim task embedding (from ONNX)
 * - Hidden: 128-dim layer with ReLU
 * - Output: 8-dim softmax weights
 *
 * @module moe-router
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import { dirname, join } from 'path';

// ============================================================================
// Types & Constants
// ============================================================================

/**
 * Expert type definitions (8 experts)
 */
export type ExpertType =
  | 'coder'
  | 'tester'
  | 'reviewer'
  | 'architect'
  | 'security'
  | 'performance'
  | 'researcher'
  | 'coordinator';

/**
 * Expert names in order (index corresponds to expert slot)
 */
export const EXPERT_NAMES: ExpertType[] = [
  'coder',
  'tester',
  'reviewer',
  'architect',
  'security',
  'performance',
  'researcher',
  'coordinator',
];

/**
 * Number of experts (fixed at 8)
 */
export const NUM_EXPERTS = 8;

/**
 * Input dimension (384 from ONNX MiniLM-L6-v2)
 */
export const INPUT_DIM = 384;

/**
 * Hidden layer dimension
 */
export const HIDDEN_DIM = 128;

/**
 * MoE Router configuration
 */
export interface MoERouterConfig {
  /** Top-k experts to route to (default: 2) */
  topK: number;
  /** Learning rate for online updates (default: 0.01) */
  learningRate: number;
  /** Temperature for softmax (default: 1.0) */
  temperature: number;
  /** Load balancing coefficient (default: 0.01) */
  loadBalanceCoef: number;
  /** Path for weight persistence (default: '.swarm/moe-weights.json') */
  weightsPath: string;
  /** Auto-save interval in updates (default: 50) */
  autoSaveInterval: number;
  /** Enable noise for exploration (default: true) */
  enableNoise: boolean;
  /** Noise standard deviation (default: 0.1) */
  noiseStd: number;
}

/**
 * Expert routing result
 */
export interface RoutingResult {
  /** Selected experts with weights */
  experts: Array<{
    name: ExpertType;
    index: number;
    weight: number;
    score: number;
  }>;
  /** Raw gating scores (all experts) */
  allScores: number[];
  /** Load balance loss */
  loadBalanceLoss: number;
  /** Entropy of routing distribution */
  entropy: number;
}

/**
 * Expert utilization statistics
 */
export interface LoadBalanceStats {
  /** Per-expert utilization (0-1) */
  utilization: Record<ExpertType, number>;
  /** Total routing count */
  totalRoutings: number;
  /** Per-expert routing count */
  routingCounts: Record<ExpertType, number>;
  /** Gini coefficient of load (0 = perfect balance, 1 = all to one) */
  giniCoefficient: number;
  /** Coefficient of variation */
  coefficientOfVariation: number;
}

/**
 * Persisted model structure
 */
interface PersistedModel {
  version: string;
  config: Partial<MoERouterConfig>;
  weights: {
    W1: number[][];
    b1: number[];
    W2: number[][];
    b2: number[];
  };
  stats: {
    updateCount: number;
    routingCounts: number[];
    avgReward: number;
  };
  metadata: {
    savedAt: string;
    expertNames: string[];
  };
}

/**
 * Default configuration
 */
const DEFAULT_CONFIG: MoERouterConfig = {
  topK: 2,
  learningRate: 0.01,
  temperature: 1.0,
  loadBalanceCoef: 0.01,
  weightsPath: '.swarm/moe-weights.json',
  autoSaveInterval: 50,
  enableNoise: true,
  noiseStd: 0.1,
};

// ============================================================================
// Matrix Operations
// ============================================================================

/**
 * Initialize weights using Xavier/Glorot initialization
 */
function xavierInit(fanIn: number, fanOut: number): Float32Array {
  const std = Math.sqrt(2.0 / (fanIn + fanOut));
  const weights = new Float32Array(fanIn * fanOut);
  for (let i = 0; i < weights.length; i++) {
    // Box-Muller transform for normal distribution
    const u1 = Math.random();
    const u2 = Math.random();
    const z = Math.sqrt(-2 * Math.log(u1 + 1e-8)) * Math.cos(2 * Math.PI * u2);
    weights[i] = z * std;
  }
  return weights;
}

/**
 * Matrix-vector multiplication: y = Wx
 * W is stored row-major: [rows * cols]
 */
function matmul(
  W: Float32Array,
  x: Float32Array,
  rows: number,
  cols: number,
  out: Float32Array
): void {
  for (let i = 0; i < rows; i++) {
    let sum = 0;
    const rowOffset = i * cols;
    // 4x loop unrolling for SIMD-friendly access
    let j = 0;
    for (; j + 3 < cols; j += 4) {
      sum +=
        W[rowOffset + j] * x[j] +
        W[rowOffset + j + 1] * x[j + 1] +
        W[rowOffset + j + 2] * x[j + 2] +
        W[rowOffset + j + 3] * x[j + 3];
    }
    // Handle remainder
    for (; j < cols; j++) {
      sum += W[rowOffset + j] * x[j];
    }
    out[i] = sum;
  }
}

/**
 * Vector addition: y = x + b
 */
function addBias(x: Float32Array, b: Float32Array, out: Float32Array): void {
  for (let i = 0; i < x.length; i++) {
    out[i] = x[i] + b[i];
  }
}

/**
 * ReLU activation: y = max(0, x)
 */
function relu(x: Float32Array, out: Float32Array): void {
  for (let i = 0; i < x.length; i++) {
    out[i] = x[i] > 0 ? x[i] : 0;
  }
}

/**
 * Softmax with temperature: y_i = exp(x_i/T) / sum(exp(x_j/T))
 */
function softmax(x: Float32Array, temperature: number, out: Float32Array): void {
  // Find max for numerical stability
  let maxVal = x[0];
  for (let i = 1; i < x.length; i++) {
    if (x[i] > maxVal) maxVal = x[i];
  }

  // Compute exp and sum
  let sum = 0;
  for (let i = 0; i < x.length; i++) {
    out[i] = Math.exp((x[i] - maxVal) / temperature);
    sum += out[i];
  }

  // Normalize
  const invSum = 1.0 / (sum + 1e-8);
  for (let i = 0; i < x.length; i++) {
    out[i] *= invSum;
  }
}

/**
 * Compute entropy of distribution: H = -sum(p * log(p))
 */
function entropy(p: Float32Array): number {
  let h = 0;
  for (let i = 0; i < p.length; i++) {
    if (p[i] > 1e-8) {
      h -= p[i] * Math.log(p[i]);
    }
  }
  return h;
}

/**
 * Add Gaussian noise for exploration
 */
function addNoise(x: Float32Array, std: number, out: Float32Array): void {
  for (let i = 0; i < x.length; i++) {
    const u1 = Math.random();
    const u2 = Math.random();
    const z = Math.sqrt(-2 * Math.log(u1 + 1e-8)) * Math.cos(2 * Math.PI * u2);
    out[i] = x[i] + z * std;
  }
}

// ============================================================================
// MoE Router Implementation
// ============================================================================

/**
 * Mixture of Experts Router
 *
 * Implements a two-layer gating network:
 * - Layer 1: Linear(384, 128) + ReLU
 * - Layer 2: Linear(128, 8) + Softmax
 *
 * Uses top-k expert selection with load balancing.
 */
export class MoERouter {
  private config: MoERouterConfig;

  // Network weights (pre-allocated Float32Arrays)
  private W1: Float32Array; // [HIDDEN_DIM x INPUT_DIM]
  private b1: Float32Array; // [HIDDEN_DIM]
  private W2: Float32Array; // [NUM_EXPERTS x HIDDEN_DIM]
  private b2: Float32Array; // [NUM_EXPERTS]

  // Intermediate buffers (pre-allocated, no GC pressure)
  private hidden: Float32Array; // [HIDDEN_DIM]
  private hiddenWithBias: Float32Array; // [HIDDEN_DIM]
  private hiddenActivated: Float32Array; // [HIDDEN_DIM]
  private logits: Float32Array; // [NUM_EXPERTS]
  private logitsWithBias: Float32Array; // [NUM_EXPERTS]
  private noisyLogits: Float32Array; // [NUM_EXPERTS]
  private probs: Float32Array; // [NUM_EXPERTS]

  // Gradient buffers for online learning
  private gradW2: Float32Array; // [NUM_EXPERTS x HIDDEN_DIM]
  private gradb2: Float32Array; // [NUM_EXPERTS]
  private gradW1: Float32Array; // [HIDDEN_DIM x INPUT_DIM]
  private gradb1: Float32Array; // [HIDDEN_DIM]
  private gradHidden: Float32Array; // [HIDDEN_DIM]

  // Statistics
  private routingCounts: Float32Array; // [NUM_EXPERTS]
  private totalRoutings = 0;
  private updateCount = 0;
  private avgReward = 0;

  // Cache for last input (for gradient computation)
  private lastInput: Float32Array | null = null;
  private lastHiddenActivated: Float32Array | null = null;
  private lastProbs: Float32Array | null = null;
  private lastSelectedExperts: number[] = [];

  constructor(config: Partial<MoERouterConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };

    // Initialize weights
    this.W1 = xavierInit(INPUT_DIM, HIDDEN_DIM);
    this.b1 = new Float32Array(HIDDEN_DIM);
    this.W2 = xavierInit(HIDDEN_DIM, NUM_EXPERTS);
    this.b2 = new Float32Array(NUM_EXPERTS);

    // Pre-allocate intermediate buffers
    this.hidden = new Float32Array(HIDDEN_DIM);
    this.hiddenWithBias = new Float32Array(HIDDEN_DIM);
    this.hiddenActivated = new Float32Array(HIDDEN_DIM);
    this.logits = new Float32Array(NUM_EXPERTS);
    this.logitsWithBias = new Float32Array(NUM_EXPERTS);
    this.noisyLogits = new Float32Array(NUM_EXPERTS);
    this.probs = new Float32Array(NUM_EXPERTS);

    // Pre-allocate gradient buffers
    this.gradW2 = new Float32Array(NUM_EXPERTS * HIDDEN_DIM);
    this.gradb2 = new Float32Array(NUM_EXPERTS);
    this.gradW1 = new Float32Array(HIDDEN_DIM * INPUT_DIM);
    this.gradb1 = new Float32Array(HIDDEN_DIM);
    this.gradHidden = new Float32Array(HIDDEN_DIM);

    // Statistics
    this.routingCounts = new Float32Array(NUM_EXPERTS);
  }

  /**
   * Initialize router, loading persisted weights if available
   */
  async initialize(): Promise<void> {
    await this.loadWeights();
  }

  /**
   * Route task to top-k experts based on embedding
   *
   * @param taskEmbedding - 384-dim task embedding from ONNX
   * @returns Routing result with selected experts and weights
   */
  route(taskEmbedding: Float32Array | number[]): RoutingResult {
    // Convert to Float32Array if needed
    const input =
      taskEmbedding instanceof Float32Array
        ? taskEmbedding
        : new Float32Array(taskEmbedding);

    // Validate input dimension
    if (input.length !== INPUT_DIM) {
      throw new Error(
        `Expected embedding dimension ${INPUT_DIM}, got ${input.length}`
      );
    }

    // Forward pass through gating network
    // Layer 1: Linear + ReLU
    matmul(this.W1, input, HIDDEN_DIM, INPUT_DIM, this.hidden);
    addBias(this.hidden, this.b1, this.hiddenWithBias);
    relu(this.hiddenWithBias, this.hiddenActivated);

    // Layer 2: Linear
    matmul(this.W2, this.hiddenActivated, NUM_EXPERTS, HIDDEN_DIM, this.logits);
    addBias(this.logits, this.b2, this.logitsWithBias);

    // Add noise for exploration if enabled
    if (this.config.enableNoise) {
      addNoise(this.logitsWithBias, this.config.noiseStd, this.noisyLogits);
    } else {
      this.noisyLogits.set(this.logitsWithBias);
    }

    // Softmax to get probabilities
    softmax(this.noisyLogits, this.config.temperature, this.probs);

    // Select top-k experts
    const expertIndices = this.selectTopK(this.probs, this.config.topK);

    // Compute load balance loss
    const loadBalanceLoss = this.computeLoadBalanceLoss();

    // Compute entropy
    const routingEntropy = entropy(this.probs);

    // Update statistics
    for (const idx of expertIndices) {
      this.routingCounts[idx]++;
    }
    this.totalRoutings++;

    // Cache for gradient computation
    this.lastInput = new Float32Array(input);
    this.lastHiddenActivated = new Float32Array(this.hiddenActivated);
    this.lastProbs = new Float32Array(this.probs);
    this.lastSelectedExperts = expertIndices;

    // Build result
    const totalWeight = expertIndices.reduce((sum, idx) => sum + this.probs[idx], 0);
    const experts = expertIndices.map((idx) => ({
      name: EXPERT_NAMES[idx],
      index: idx,
      weight: this.probs[idx] / (totalWeight + 1e-8), // Normalize weights
      score: this.probs[idx],
    }));

    return {
      experts,
      allScores: Array.from(this.probs),
      loadBalanceLoss,
      entropy: routingEntropy,
    };
  }

  /**
   * Update expert weights based on reward signal
   *
   * Uses REINFORCE-style gradient update:
   * gradient = reward * d_log_prob / d_weights
   *
   * @param expert - Expert that received the reward
   * @param reward - Reward signal (-1 to 1, positive = good)
   */
  updateExpertWeights(expert: ExpertType | number, reward: number): void {
    const expertIdx = typeof expert === 'number' ? expert : EXPERT_NAMES.indexOf(expert);

    if (expertIdx < 0 || expertIdx >= NUM_EXPERTS) {
      console.warn(`[MoE] Invalid expert: ${expert}`);
      return;
    }

    if (!this.lastInput || !this.lastHiddenActivated || !this.lastProbs) {
      console.warn('[MoE] No cached forward pass for gradient computation');
      return;
    }

    // Clamp reward to [-1, 1]
    const clampedReward = Math.max(-1, Math.min(1, reward));

    // Compute gradients using REINFORCE
    // For softmax: d_log_p_i / d_logit_j = delta_ij - p_j
    // gradient = reward * (1 - p_expert) for selected expert
    // gradient = reward * (-p_j) for other experts

    // Clear gradient buffers
    this.gradW2.fill(0);
    this.gradb2.fill(0);
    this.gradW1.fill(0);
    this.gradb1.fill(0);
    this.gradHidden.fill(0);

    // Gradient w.r.t. logits (before softmax)
    for (let i = 0; i < NUM_EXPERTS; i++) {
      if (i === expertIdx) {
        this.gradb2[i] = clampedReward * (1 - this.lastProbs[i]);
      } else {
        this.gradb2[i] = clampedReward * (-this.lastProbs[i]);
      }
    }

    // Gradient w.r.t. W2: outer product of gradb2 and hiddenActivated
    for (let i = 0; i < NUM_EXPERTS; i++) {
      const rowOffset = i * HIDDEN_DIM;
      for (let j = 0; j < HIDDEN_DIM; j++) {
        this.gradW2[rowOffset + j] = this.gradb2[i] * this.lastHiddenActivated[j];
      }
    }

    // Backprop through W2 to get gradient w.r.t. hidden
    for (let j = 0; j < HIDDEN_DIM; j++) {
      let sum = 0;
      for (let i = 0; i < NUM_EXPERTS; i++) {
        sum += this.gradb2[i] * this.W2[i * HIDDEN_DIM + j];
      }
      this.gradHidden[j] = sum;
    }

    // Backprop through ReLU: gradient is 0 where activation was 0
    for (let j = 0; j < HIDDEN_DIM; j++) {
      if (this.lastHiddenActivated[j] <= 0) {
        this.gradHidden[j] = 0;
      }
    }

    // Gradient w.r.t. b1
    this.gradb1.set(this.gradHidden);

    // Gradient w.r.t. W1: outer product of gradHidden and input
    for (let i = 0; i < HIDDEN_DIM; i++) {
      const rowOffset = i * INPUT_DIM;
      for (let j = 0; j < INPUT_DIM; j++) {
        this.gradW1[rowOffset + j] = this.gradHidden[i] * this.lastInput[j];
      }
    }

    // Apply gradients with learning rate
    const lr = this.config.learningRate;
    for (let i = 0; i < this.W2.length; i++) {
      this.W2[i] += lr * this.gradW2[i];
    }
    for (let i = 0; i < this.b2.length; i++) {
      this.b2[i] += lr * this.gradb2[i];
    }
    for (let i = 0; i < this.W1.length; i++) {
      this.W1[i] += lr * this.gradW1[i];
    }
    for (let i = 0; i < this.b1.length; i++) {
      this.b1[i] += lr * this.gradb1[i];
    }

    // Update statistics
    this.updateCount++;
    this.avgReward = (this.avgReward * (this.updateCount - 1) + clampedReward) / this.updateCount;

    // Auto-save
    if (
      this.config.autoSaveInterval > 0 &&
      this.updateCount % this.config.autoSaveInterval === 0
    ) {
      this.saveWeights().catch(() => {}); // Fire and forget
    }
  }

  /**
   * Get load balance statistics across all experts
   */
  getLoadBalance(): LoadBalanceStats {
    const counts: Record<ExpertType, number> = {} as Record<ExpertType, number>;
    const utilization: Record<ExpertType, number> = {} as Record<ExpertType, number>;

    const total = this.totalRoutings || 1;
    const idealUtilization = 1 / NUM_EXPERTS;

    for (let i = 0; i < NUM_EXPERTS; i++) {
      const name = EXPERT_NAMES[i];
      counts[name] = this.routingCounts[i];
      utilization[name] = this.routingCounts[i] / total;
    }

    // Compute Gini coefficient
    const gini = this.computeGiniCoefficient();

    // Compute coefficient of variation
    const mean = total / NUM_EXPERTS;
    let variance = 0;
    for (let i = 0; i < NUM_EXPERTS; i++) {
      variance += Math.pow(this.routingCounts[i] - mean, 2);
    }
    variance /= NUM_EXPERTS;
    const cv = Math.sqrt(variance) / (mean + 1e-8);

    return {
      utilization,
      totalRoutings: this.totalRoutings,
      routingCounts: counts,
      giniCoefficient: gini,
      coefficientOfVariation: cv,
    };
  }

  /**
   * Get router statistics
   */
  getStats(): Record<string, number | string> {
    return {
      totalRoutings: this.totalRoutings,
      updateCount: this.updateCount,
      avgReward: this.avgReward,
      topK: this.config.topK,
      temperature: this.config.temperature,
      learningRate: this.config.learningRate,
      giniCoefficient: this.computeGiniCoefficient(),
    };
  }

  /**
   * Reset all statistics and routing counts
   */
  resetStats(): void {
    this.routingCounts.fill(0);
    this.totalRoutings = 0;
    this.updateCount = 0;
    this.avgReward = 0;
  }

  /**
   * Load weights from persistence file
   */
  async loadWeights(path?: string): Promise<boolean> {
    const weightsPath = path || this.config.weightsPath;
    try {
      if (!existsSync(weightsPath)) {
        return false;
      }

      const data = readFileSync(weightsPath, 'utf-8');
      const model: PersistedModel = JSON.parse(data);

      // Validate version
      if (!model.version || !model.version.startsWith('1.')) {
        console.warn(`[MoE] Incompatible model version: ${model.version}`);
        return false;
      }

      // Load weights
      this.W1 = new Float32Array(model.weights.W1.flat());
      this.b1 = new Float32Array(model.weights.b1);
      this.W2 = new Float32Array(model.weights.W2.flat());
      this.b2 = new Float32Array(model.weights.b2);

      // Load stats
      this.updateCount = model.stats.updateCount || 0;
      this.avgReward = model.stats.avgReward || 0;
      this.routingCounts = new Float32Array(
        model.stats.routingCounts || new Array(NUM_EXPERTS).fill(0)
      );
      this.totalRoutings = this.routingCounts.reduce((a, b) => a + b, 0);

      return true;
    } catch (err) {
      console.warn(`[MoE] Failed to load weights: ${err}`);
      return false;
    }
  }

  /**
   * Save weights to persistence file
   */
  async saveWeights(path?: string): Promise<boolean> {
    const weightsPath = path || this.config.weightsPath;
    try {
      // Ensure directory exists
      const dir = dirname(weightsPath);
      if (!existsSync(dir)) {
        mkdirSync(dir, { recursive: true });
      }

      // Convert Float32Arrays to nested arrays for JSON
      const W1_2d: number[][] = [];
      for (let i = 0; i < HIDDEN_DIM; i++) {
        W1_2d.push(Array.from(this.W1.slice(i * INPUT_DIM, (i + 1) * INPUT_DIM)));
      }

      const W2_2d: number[][] = [];
      for (let i = 0; i < NUM_EXPERTS; i++) {
        W2_2d.push(Array.from(this.W2.slice(i * HIDDEN_DIM, (i + 1) * HIDDEN_DIM)));
      }

      const model: PersistedModel = {
        version: '1.0.0',
        config: {
          topK: this.config.topK,
          temperature: this.config.temperature,
          learningRate: this.config.learningRate,
          loadBalanceCoef: this.config.loadBalanceCoef,
        },
        weights: {
          W1: W1_2d,
          b1: Array.from(this.b1),
          W2: W2_2d,
          b2: Array.from(this.b2),
        },
        stats: {
          updateCount: this.updateCount,
          routingCounts: Array.from(this.routingCounts),
          avgReward: this.avgReward,
        },
        metadata: {
          savedAt: new Date().toISOString(),
          expertNames: [...EXPERT_NAMES],
        },
      };

      writeFileSync(weightsPath, JSON.stringify(model, null, 2));
      return true;
    } catch (err) {
      console.warn(`[MoE] Failed to save weights: ${err}`);
      return false;
    }
  }

  /**
   * Reset weights to random initialization
   */
  resetWeights(): void {
    this.W1 = xavierInit(INPUT_DIM, HIDDEN_DIM);
    this.b1.fill(0);
    this.W2 = xavierInit(HIDDEN_DIM, NUM_EXPERTS);
    this.b2.fill(0);
    this.resetStats();
  }

  // ============================================================================
  // Private Methods
  // ============================================================================

  /**
   * Select top-k indices from probabilities
   */
  private selectTopK(probs: Float32Array, k: number): number[] {
    // Create index-value pairs and sort by value descending
    const pairs: Array<[number, number]> = [];
    for (let i = 0; i < probs.length; i++) {
      pairs.push([i, probs[i]]);
    }
    pairs.sort((a, b) => b[1] - a[1]);

    // Return top-k indices
    return pairs.slice(0, k).map((p) => p[0]);
  }

  /**
   * Compute load balance loss for regularization
   *
   * Uses auxiliary loss from Switch Transformer:
   * L_balance = N * sum(f_i * P_i)
   * where f_i = fraction of tokens routed to expert i
   *       P_i = average routing probability to expert i
   */
  private computeLoadBalanceLoss(): number {
    if (this.totalRoutings === 0) return 0;

    let loss = 0;
    for (let i = 0; i < NUM_EXPERTS; i++) {
      const fraction = this.routingCounts[i] / this.totalRoutings;
      const avgProb = this.probs[i]; // Current routing prob
      loss += fraction * avgProb;
    }

    return NUM_EXPERTS * loss * this.config.loadBalanceCoef;
  }

  /**
   * Compute Gini coefficient for load distribution
   */
  private computeGiniCoefficient(): number {
    if (this.totalRoutings === 0) return 0;

    // Sort counts
    const sorted = Array.from(this.routingCounts).sort((a, b) => a - b);
    const n = sorted.length;
    const mean = this.totalRoutings / n;

    // Compute Gini using the formula: G = (2 * sum(i * x_i) - (n+1) * sum(x_i)) / (n * sum(x_i))
    let weightedSum = 0;
    for (let i = 0; i < n; i++) {
      weightedSum += (i + 1) * sorted[i];
    }

    const gini =
      (2 * weightedSum - (n + 1) * this.totalRoutings) /
      (n * this.totalRoutings + 1e-8);

    return Math.max(0, gini);
  }
}

// ============================================================================
// Singleton Instance
// ============================================================================

let moeRouterInstance: MoERouter | null = null;

/**
 * Get singleton MoE router instance
 *
 * @param config - Optional configuration (only used on first call)
 * @returns MoE router instance
 */
export function getMoERouter(config?: Partial<MoERouterConfig>): MoERouter {
  if (!moeRouterInstance) {
    moeRouterInstance = new MoERouter(config);
    // Initialize in background (load weights)
    moeRouterInstance.initialize().catch((err) => {
      console.warn('[MoE] Failed to initialize router:', err);
    });
  }
  return moeRouterInstance;
}

/**
 * Reset singleton instance (for testing)
 */
export function resetMoERouter(): void {
  moeRouterInstance = null;
}

/**
 * Factory function to create new router
 */
export function createMoERouter(config?: Partial<MoERouterConfig>): MoERouter {
  return new MoERouter(config);
}

/**
 * Pattern Learner
 *
 * Implements pattern extraction, matching, and evolution for
 * continuous learning from agent experiences.
 *
 * Performance Targets:
 * - Pattern matching: <1ms
 * - Pattern extraction: <5ms
 * - Evolution step: <2ms
 */

import type {
  Pattern,
  PatternMatch,
  PatternEvolution,
  Trajectory,
  DistilledMemory,
  NeuralEvent,
  NeuralEventListener,
} from './types.js';
import { deepEncode, deepDecode } from './utils/serialize.js';

/**
 * Configuration for Pattern Learner
 */
export interface PatternLearnerConfig {
  /** Maximum number of patterns to store */
  maxPatterns: number;

  /** Similarity threshold for matching */
  matchThreshold: number;

  /** Minimum usages before pattern is stable */
  minUsagesForStable: number;

  /** Quality threshold for pattern inclusion */
  qualityThreshold: number;

  /** Enable pattern clustering */
  enableClustering: boolean;

  /** Number of clusters (if clustering enabled) */
  numClusters: number;

  /** Evolution learning rate */
  evolutionLearningRate: number;
}

/**
 * Default Pattern Learner configuration
 */
const DEFAULT_CONFIG: PatternLearnerConfig = {
  maxPatterns: 1000,
  matchThreshold: 0.7,
  minUsagesForStable: 5,
  qualityThreshold: 0.5,
  enableClustering: true,
  numClusters: 50,
  evolutionLearningRate: 0.1,
};

/**
 * Cluster representation for fast pattern lookup
 */
interface PatternCluster {
  clusterId: number;
  centroid: Float32Array;
  patternIds: Set<string>;
}

/**
 * Pattern Learner - Manages pattern extraction, matching, and evolution
 */
export class PatternLearner {
  private config: PatternLearnerConfig;
  private patterns: Map<string, Pattern> = new Map();
  private clusters: PatternCluster[] = [];
  private patternToCluster: Map<string, number> = new Map();

  // Performance tracking
  private matchCount = 0;
  private totalMatchTime = 0;
  private extractionCount = 0;
  private totalExtractionTime = 0;
  private evolutionCount = 0;
  private totalEvolutionTime = 0;

  // Event listeners
  private eventListeners: Set<NeuralEventListener> = new Set();

  constructor(config: Partial<PatternLearnerConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  // ==========================================================================
  // Pattern Matching
  // ==========================================================================

  /**
   * Find matching patterns for a query embedding
   * Target: <1ms
   */
  findMatches(queryEmbedding: Float32Array, k: number = 3): PatternMatch[] {
    const startTime = performance.now();

    if (this.patterns.size === 0) {
      return [];
    }

    let candidates: Pattern[];

    // Use clustering for faster search if enabled and clusters exist
    if (this.config.enableClustering && this.clusters.length > 0) {
      candidates = this.getCandidatesFromClusters(queryEmbedding);
    } else {
      candidates = Array.from(this.patterns.values());
    }

    // Compute similarities
    const matches: PatternMatch[] = [];

    for (const pattern of candidates) {
      const similarity = this.cosineSimilarity(queryEmbedding, pattern.embedding);

      if (similarity >= this.config.matchThreshold) {
        matches.push({
          pattern,
          similarity,
          confidence: this.computeMatchConfidence(pattern, similarity),
          latencyMs: 0,
        });
      }
    }

    // Sort by similarity
    matches.sort((a, b) => b.similarity - a.similarity);
    const result = matches.slice(0, k);

    // Track performance
    const elapsed = performance.now() - startTime;
    this.matchCount++;
    this.totalMatchTime += elapsed;

    // Warn if over target
    if (elapsed > 1) {
      console.warn(`Pattern matching exceeded target: ${elapsed.toFixed(2)}ms > 1ms`);
    }

    return result;
  }

  /**
   * Find best single match
   */
  findBestMatch(queryEmbedding: Float32Array): PatternMatch | null {
    const matches = this.findMatches(queryEmbedding, 1);
    return matches.length > 0 ? matches[0] : null;
  }

  // ==========================================================================
  // Pattern Extraction
  // ==========================================================================

  /**
   * Extract a pattern from a trajectory
   * Target: <5ms
   */
  extractPattern(trajectory: Trajectory, memory?: DistilledMemory): Pattern | null {
    const startTime = performance.now();

    // Validate trajectory
    if (!trajectory.isComplete || trajectory.qualityScore < this.config.qualityThreshold) {
      return null;
    }

    // Check for duplicates
    const embedding = this.computePatternEmbedding(trajectory);
    const existing = this.findSimilarPattern(embedding, 0.95);

    if (existing) {
      // Update existing pattern instead
      this.updatePatternFromTrajectory(existing, trajectory);
      return existing;
    }

    // Create new pattern
    const pattern: Pattern = {
      patternId: `pat_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      name: this.generatePatternName(trajectory),
      domain: trajectory.domain,
      embedding,
      strategy: this.extractStrategy(trajectory),
      successRate: trajectory.qualityScore,
      usageCount: 1,
      qualityHistory: [trajectory.qualityScore],
      evolutionHistory: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };

    // Store pattern
    this.patterns.set(pattern.patternId, pattern);

    // Update clusters if enabled
    if (this.config.enableClustering) {
      this.assignToCluster(pattern);
    }

    // Prune if over capacity
    if (this.patterns.size > this.config.maxPatterns) {
      this.prunePatterns();
    }

    // Track performance
    const elapsed = performance.now() - startTime;
    this.extractionCount++;
    this.totalExtractionTime += elapsed;

    return pattern;
  }

  /**
   * Extract patterns from multiple trajectories in batch
   */
  extractPatternsBatch(trajectories: Trajectory[]): Pattern[] {
    const patterns: Pattern[] = [];

    for (const trajectory of trajectories) {
      const pattern = this.extractPattern(trajectory);
      if (pattern) {
        patterns.push(pattern);
      }
    }

    // Rebuild clusters after batch extraction
    if (this.config.enableClustering && patterns.length > 10) {
      this.rebuildClusters();
    }

    return patterns;
  }

  // ==========================================================================
  // Pattern Evolution
  // ==========================================================================

  /**
   * Evolve a pattern based on new experience
   * Target: <2ms
   */
  evolvePattern(patternId: string, quality: number, context?: string): void {
    const startTime = performance.now();

    const pattern = this.patterns.get(patternId);
    if (!pattern) return;

    const previousQuality = pattern.successRate;
    const lr = this.config.evolutionLearningRate;

    // Update quality history
    pattern.qualityHistory.push(quality);
    if (pattern.qualityHistory.length > 100) {
      pattern.qualityHistory = pattern.qualityHistory.slice(-100);
    }

    // Exponential moving average for success rate
    pattern.successRate = pattern.successRate * (1 - lr) + quality * lr;
    pattern.usageCount++;
    pattern.updatedAt = Date.now();

    // Record evolution
    const evolutionType = this.determineEvolutionType(previousQuality, pattern.successRate);
    pattern.evolutionHistory.push({
      timestamp: Date.now(),
      type: evolutionType,
      previousQuality,
      newQuality: pattern.successRate,
      description: context || 'Updated from new experience',
    });

    // Keep evolution history bounded
    if (pattern.evolutionHistory.length > 50) {
      pattern.evolutionHistory = pattern.evolutionHistory.slice(-50);
    }

    // Emit event
    this.emitEvent({
      type: 'pattern_evolved',
      patternId,
      evolutionType,
    });

    // Track performance
    const elapsed = performance.now() - startTime;
    this.evolutionCount++;
    this.totalEvolutionTime += elapsed;
  }

  /**
   * Merge two similar patterns
   */
  mergePatterns(patternId1: string, patternId2: string): Pattern | null {
    const p1 = this.patterns.get(patternId1);
    const p2 = this.patterns.get(patternId2);

    if (!p1 || !p2) return null;

    // Keep the higher quality pattern as base
    const [keep, remove] = p1.successRate >= p2.successRate ? [p1, p2] : [p2, p1];

    // Merge embeddings (weighted average)
    const totalUsage = keep.usageCount + remove.usageCount;
    const w1 = keep.usageCount / totalUsage;
    const w2 = remove.usageCount / totalUsage;

    for (let i = 0; i < keep.embedding.length; i++) {
      keep.embedding[i] = keep.embedding[i] * w1 + remove.embedding[i] * w2;
    }

    // Merge statistics
    keep.usageCount += remove.usageCount;
    keep.qualityHistory.push(...remove.qualityHistory);
    keep.successRate = keep.qualityHistory.reduce((a, b) => a + b, 0) / keep.qualityHistory.length;

    // Record merge
    keep.evolutionHistory.push({
      timestamp: Date.now(),
      type: 'merge',
      previousQuality: p1.successRate,
      newQuality: keep.successRate,
      description: `Merged with pattern ${remove.patternId}`,
    });

    // Remove the merged pattern
    this.patterns.delete(remove.patternId);
    this.patternToCluster.delete(remove.patternId);

    return keep;
  }

  /**
   * Split a pattern into more specific sub-patterns
   */
  splitPattern(patternId: string, numSplits: number = 2): Pattern[] {
    const pattern = this.patterns.get(patternId);
    if (!pattern || numSplits < 2) return [];

    const splits: Pattern[] = [];

    for (let i = 0; i < numSplits; i++) {
      // Create variation of embedding with noise
      const newEmbedding = new Float32Array(pattern.embedding.length);
      for (let j = 0; j < newEmbedding.length; j++) {
        const noise = (Math.random() - 0.5) * 0.1;
        newEmbedding[j] = pattern.embedding[j] + noise;
      }

      const newPattern: Pattern = {
        patternId: `pat_${Date.now()}_${i}_${Math.random().toString(36).slice(2, 6)}`,
        name: `${pattern.name}_split_${i}`,
        domain: pattern.domain,
        embedding: newEmbedding,
        strategy: pattern.strategy,
        successRate: pattern.successRate * 0.9, // Slight penalty for uncertainty
        usageCount: 0,
        qualityHistory: [],
        evolutionHistory: [{
          timestamp: Date.now(),
          type: 'split',
          previousQuality: pattern.successRate,
          newQuality: pattern.successRate * 0.9,
          description: `Split from pattern ${patternId}`,
        }],
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };

      this.patterns.set(newPattern.patternId, newPattern);
      splits.push(newPattern);
    }

    // Remove original pattern
    this.patterns.delete(patternId);
    this.patternToCluster.delete(patternId);

    // Rebuild clusters
    if (this.config.enableClustering) {
      this.rebuildClusters();
    }

    return splits;
  }

  // ==========================================================================
  // Pattern Access
  // ==========================================================================

  /**
   * Get all patterns
   */
  getPatterns(): Pattern[] {
    return Array.from(this.patterns.values());
  }

  /**
   * Get pattern by ID
   */
  getPattern(patternId: string): Pattern | undefined {
    return this.patterns.get(patternId);
  }

  /**
   * Get patterns by domain
   */
  getPatternsByDomain(domain: string): Pattern[] {
    return Array.from(this.patterns.values()).filter(p => p.domain === domain);
  }

  /**
   * Get stable patterns (sufficient usage)
   */
  getStablePatterns(): Pattern[] {
    return Array.from(this.patterns.values())
      .filter(p => p.usageCount >= this.config.minUsagesForStable);
  }

  // ==========================================================================
  // Statistics
  // ==========================================================================

  getStats(): Record<string, number> {
    const patterns = Array.from(this.patterns.values());

    return {
      totalPatterns: this.patterns.size,
      stablePatterns: patterns.filter(p => p.usageCount >= this.config.minUsagesForStable).length,
      avgSuccessRate: patterns.length > 0
        ? patterns.reduce((s, p) => s + p.successRate, 0) / patterns.length
        : 0,
      avgUsageCount: patterns.length > 0
        ? patterns.reduce((s, p) => s + p.usageCount, 0) / patterns.length
        : 0,
      numClusters: this.clusters.length,
      avgMatchTimeMs: this.matchCount > 0 ? this.totalMatchTime / this.matchCount : 0,
      avgExtractionTimeMs: this.extractionCount > 0 ? this.totalExtractionTime / this.extractionCount : 0,
      avgEvolutionTimeMs: this.evolutionCount > 0 ? this.totalEvolutionTime / this.evolutionCount : 0,
      // #1773 item 2 — search-path observability. PatternLearner currently
      // uses cluster-aware brute-force exclusively (no HNSW yet); this flag
      // is exposed so the dashboard can report which retrieval substrate
      // was actually used. Unlike ReasoningBank which CAN dispatch to HNSW,
      // PatternLearner.findMatches always takes the brute-force path until
      // a follow-up wires AgentDB into pattern matching too.
      hnswEnabled: 0,
      bruteForceMatches: this.matchCount,
    };
  }

  // ==========================================================================
  // Persistence (#1773 Phase 1.6)
  // ==========================================================================

  /**
   * Serialize learner state to a JSON-safe object. Round-trips losslessly
   * through `JSON.stringify` → file → `JSON.parse` → `deserialize()`.
   * Float32Array embeddings encode as `{__f32: number[]}`, Maps as
   * `{__map: [[k,v], …]}`. Sets become arrays. Excludes event listeners
   * (callers re-register on restore).
   */
  serialize(): unknown {
    return deepEncode({
      schemaVersion: 1,
      config: this.config,
      patterns: this.patterns,
      clusters: this.clusters.map((c) => ({
        clusterId: c.clusterId,
        centroid: c.centroid,
        patternIds: Array.from(c.patternIds),
      })),
      patternToCluster: this.patternToCluster,
      counters: {
        matchCount: this.matchCount,
        totalMatchTime: this.totalMatchTime,
        extractionCount: this.extractionCount,
        totalExtractionTime: this.totalExtractionTime,
        evolutionCount: this.evolutionCount,
        totalEvolutionTime: this.totalEvolutionTime,
      },
    });
  }

  /**
   * Restore from a previously-serialized state. Replaces all current state.
   * Event listeners NOT restored — re-register after deserialize() returns.
   */
  deserialize(state: unknown): void {
    const decoded = deepDecode(state) as {
      schemaVersion: number;
      config: PatternLearnerConfig;
      patterns: Map<string, Pattern>;
      clusters: Array<{ clusterId: number; centroid: Float32Array; patternIds: string[] }>;
      patternToCluster: Map<string, number>;
      counters: {
        matchCount: number; totalMatchTime: number;
        extractionCount: number; totalExtractionTime: number;
        evolutionCount: number; totalEvolutionTime: number;
      };
    };
    if (decoded.schemaVersion !== 1) {
      throw new Error(`PatternLearner: unsupported schemaVersion ${decoded.schemaVersion} (expected 1)`);
    }
    this.config = { ...this.config, ...decoded.config };
    this.patterns = decoded.patterns;
    this.clusters = decoded.clusters.map((c) => ({
      clusterId: c.clusterId,
      centroid: c.centroid,
      patternIds: new Set(c.patternIds),
    }));
    this.patternToCluster = decoded.patternToCluster;
    this.matchCount = decoded.counters.matchCount;
    this.totalMatchTime = decoded.counters.totalMatchTime;
    this.extractionCount = decoded.counters.extractionCount;
    this.totalExtractionTime = decoded.counters.totalExtractionTime;
    this.evolutionCount = decoded.counters.evolutionCount;
    this.totalEvolutionTime = decoded.counters.totalEvolutionTime;
  }

  // ==========================================================================
  // Event System
  // ==========================================================================

  addEventListener(listener: NeuralEventListener): void {
    this.eventListeners.add(listener);
  }

  removeEventListener(listener: NeuralEventListener): void {
    this.eventListeners.delete(listener);
  }

  private emitEvent(event: NeuralEvent): void {
    for (const listener of this.eventListeners) {
      try {
        listener(event);
      } catch (error) {
        console.error('Error in PatternLearner event listener:', error);
      }
    }
  }

  // ==========================================================================
  // Private Helper Methods
  // ==========================================================================

  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
    if (a.length !== b.length) return 0;

    let dot = 0, normA = 0, normB = 0;
    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    const denom = Math.sqrt(normA) * Math.sqrt(normB);
    return denom > 0 ? dot / denom : 0;
  }

  private computeMatchConfidence(pattern: Pattern, similarity: number): number {
    // Combine similarity with pattern reliability
    const usageWeight = Math.min(pattern.usageCount / 10, 1);
    const qualityWeight = pattern.successRate;

    return similarity * (1 - usageWeight * 0.2 - qualityWeight * 0.2) +
           usageWeight * 0.1 +
           qualityWeight * 0.1;
  }

  private getCandidatesFromClusters(queryEmbedding: Float32Array): Pattern[] {
    // Find nearest clusters
    const clusterScores: Array<{ cluster: PatternCluster; score: number }> = [];

    for (const cluster of this.clusters) {
      const score = this.cosineSimilarity(queryEmbedding, cluster.centroid);
      clusterScores.push({ cluster, score });
    }

    clusterScores.sort((a, b) => b.score - a.score);

    // Get patterns from top 3 clusters
    const candidates: Pattern[] = [];
    for (const { cluster } of clusterScores.slice(0, 3)) {
      for (const patternId of cluster.patternIds) {
        const pattern = this.patterns.get(patternId);
        if (pattern) {
          candidates.push(pattern);
        }
      }
    }

    return candidates;
  }

  private findSimilarPattern(embedding: Float32Array, threshold: number): Pattern | null {
    for (const pattern of this.patterns.values()) {
      const sim = this.cosineSimilarity(embedding, pattern.embedding);
      if (sim >= threshold) {
        return pattern;
      }
    }
    return null;
  }

  private updatePatternFromTrajectory(pattern: Pattern, trajectory: Trajectory): void {
    // Update quality
    pattern.qualityHistory.push(trajectory.qualityScore);
    if (pattern.qualityHistory.length > 100) {
      pattern.qualityHistory = pattern.qualityHistory.slice(-100);
    }

    // EMA for success rate
    const lr = this.config.evolutionLearningRate;
    pattern.successRate = pattern.successRate * (1 - lr) + trajectory.qualityScore * lr;
    pattern.usageCount++;
    pattern.updatedAt = Date.now();
  }

  private computePatternEmbedding(trajectory: Trajectory): Float32Array {
    if (trajectory.steps.length === 0) {
      return new Float32Array(768);
    }

    const dim = trajectory.steps[0].stateAfter.length;
    const embedding = new Float32Array(dim);

    // Weighted average (higher weight for later steps)
    let totalWeight = 0;
    for (let i = 0; i < trajectory.steps.length; i++) {
      const weight = (i + 1) / trajectory.steps.length;
      totalWeight += weight;
      for (let j = 0; j < dim; j++) {
        embedding[j] += trajectory.steps[i].stateAfter[j] * weight;
      }
    }

    for (let j = 0; j < dim; j++) {
      embedding[j] /= totalWeight;
    }

    return embedding;
  }

  private generatePatternName(trajectory: Trajectory): string {
    const domain = trajectory.domain;
    const quality = trajectory.qualityScore > 0.7 ? 'high' : 'mid';
    const steps = trajectory.steps.length > 5 ? 'complex' : 'simple';
    return `${domain}_${quality}_${steps}_${Date.now() % 10000}`;
  }

  private extractStrategy(trajectory: Trajectory): string {
    const actions = trajectory.steps.map(s => s.action);
    if (actions.length === 0) return 'empty';
    if (actions.length <= 3) return actions.join(' -> ');
    return `${actions.slice(0, 2).join(' -> ')} ... ${actions[actions.length - 1]}`;
  }

  private assignToCluster(pattern: Pattern): void {
    if (this.clusters.length === 0) {
      // Create first cluster
      this.clusters.push({
        clusterId: 0,
        centroid: new Float32Array(pattern.embedding),
        patternIds: new Set([pattern.patternId]),
      });
      this.patternToCluster.set(pattern.patternId, 0);
      return;
    }

    // Find nearest cluster
    let bestCluster = 0;
    let bestSim = -1;

    for (let i = 0; i < this.clusters.length; i++) {
      const sim = this.cosineSimilarity(pattern.embedding, this.clusters[i].centroid);
      if (sim > bestSim) {
        bestSim = sim;
        bestCluster = i;
      }
    }

    // Create new cluster if not similar enough and under limit
    if (bestSim < 0.7 && this.clusters.length < this.config.numClusters) {
      const newId = this.clusters.length;
      this.clusters.push({
        clusterId: newId,
        centroid: new Float32Array(pattern.embedding),
        patternIds: new Set([pattern.patternId]),
      });
      this.patternToCluster.set(pattern.patternId, newId);
    } else {
      // Add to existing cluster and update centroid
      const cluster = this.clusters[bestCluster];
      cluster.patternIds.add(pattern.patternId);
      this.patternToCluster.set(pattern.patternId, bestCluster);
      this.updateClusterCentroid(cluster);
    }
  }

  private updateClusterCentroid(cluster: PatternCluster): void {
    const dim = cluster.centroid.length;
    const newCentroid = new Float32Array(dim);
    let count = 0;

    for (const patternId of cluster.patternIds) {
      const pattern = this.patterns.get(patternId);
      if (pattern) {
        for (let i = 0; i < dim; i++) {
          newCentroid[i] += pattern.embedding[i];
        }
        count++;
      }
    }

    if (count > 0) {
      for (let i = 0; i < dim; i++) {
        newCentroid[i] /= count;
      }
      cluster.centroid = newCentroid;
    }
  }

  private rebuildClusters(): void {
    if (this.patterns.size === 0) {
      this.clusters = [];
      this.patternToCluster.clear();
      return;
    }

    const patterns = Array.from(this.patterns.values());
    const k = Math.min(this.config.numClusters, Math.ceil(patterns.length / 5));
    const dim = patterns[0].embedding.length;

    // Initialize clusters with random patterns
    this.clusters = [];
    this.patternToCluster.clear();

    const indices = new Set<number>();
    while (indices.size < k && indices.size < patterns.length) {
      indices.add(Math.floor(Math.random() * patterns.length));
    }

    let clusterId = 0;
    for (const idx of indices) {
      this.clusters.push({
        clusterId: clusterId++,
        centroid: new Float32Array(patterns[idx].embedding),
        patternIds: new Set(),
      });
    }

    // K-means iterations
    for (let iter = 0; iter < 10; iter++) {
      // Clear assignments
      for (const cluster of this.clusters) {
        cluster.patternIds.clear();
      }

      // Assign patterns to nearest cluster
      for (const pattern of patterns) {
        let bestCluster = 0;
        let bestSim = -1;

        for (let c = 0; c < this.clusters.length; c++) {
          const sim = this.cosineSimilarity(pattern.embedding, this.clusters[c].centroid);
          if (sim > bestSim) {
            bestSim = sim;
            bestCluster = c;
          }
        }

        this.clusters[bestCluster].patternIds.add(pattern.patternId);
        this.patternToCluster.set(pattern.patternId, bestCluster);
      }

      // Update centroids
      for (const cluster of this.clusters) {
        this.updateClusterCentroid(cluster);
      }
    }

    // Remove empty clusters
    this.clusters = this.clusters.filter(c => c.patternIds.size > 0);
  }

  private prunePatterns(): void {
    // Sort by score (quality * log(usage))
    const scored = Array.from(this.patterns.entries())
      .map(([id, pattern]) => ({
        id,
        pattern,
        score: pattern.successRate * Math.log(pattern.usageCount + 1),
      }))
      .sort((a, b) => a.score - b.score);

    // Remove lowest scoring patterns
    const toRemove = scored.length - Math.floor(this.config.maxPatterns * 0.8);
    for (let i = 0; i < toRemove && i < scored.length; i++) {
      this.patterns.delete(scored[i].id);
      this.patternToCluster.delete(scored[i].id);
    }

    // Rebuild clusters
    if (this.config.enableClustering) {
      this.rebuildClusters();
    }
  }

  private determineEvolutionType(
    prev: number,
    curr: number
  ): 'improvement' | 'merge' | 'split' | 'prune' {
    const delta = curr - prev;
    if (delta > 0.05) return 'improvement';
    if (delta < -0.15) return 'prune';
    return 'improvement';
  }
}

/**
 * Factory function for creating PatternLearner
 */
export function createPatternLearner(
  config?: Partial<PatternLearnerConfig>
): PatternLearner {
  return new PatternLearner(config);
}

/**
 * ReasoningBank Integration with AgentDB
 *
 * Implements the 4-step learning pipeline with real vector storage:
 * 1. RETRIEVE - Top-k memory injection with MMR diversity (using AgentDB HNSW)
 * 2. JUDGE - LLM-as-judge trajectory evaluation
 * 3. DISTILL - Extract strategy memories from trajectories
 * 4. CONSOLIDATE - Dedup, detect contradictions, prune old patterns
 *
 * Performance Targets:
 * - Retrieval: <10ms with AgentDB HNSW (150x faster than brute-force)
 * - Learning step: <10ms
 * - Consolidation: <100ms
 *
 * @module reasoning-bank
 */

import type {
  Trajectory,
  TrajectoryStep,
  TrajectoryVerdict,
  DistilledMemory,
  Pattern,
  PatternEvolution,
  NeuralEvent,
  NeuralEventListener,
} from './types.js';
import { deepEncode, deepDecode } from './utils/serialize.js';

// ============================================================================
// AgentDB Integration
// ============================================================================

let AgentDB: any;
let agentdbImportPromise: Promise<void> | undefined;

async function ensureAgentDBImport(): Promise<void> {
  if (!agentdbImportPromise) {
    agentdbImportPromise = (async () => {
      try {
        const agentdbModule: any = await import('agentdb');
        AgentDB = agentdbModule.AgentDB || agentdbModule.default;
      } catch {
        // AgentDB not available - will use fallback
        AgentDB = undefined;
      }
    })();
  }
  return agentdbImportPromise;
}

// ============================================================================
// Configuration
// ============================================================================

/**
 * Configuration for ReasoningBank
 */
export interface ReasoningBankConfig {
  /** Maximum number of trajectories to store */
  maxTrajectories: number;

  /** Minimum quality threshold for distillation */
  distillationThreshold: number;

  /** Number of similar memories to retrieve */
  retrievalK: number;

  /** Diversity factor for MMR (0-1) */
  mmrLambda: number;

  /** Maximum age of patterns in days */
  maxPatternAgeDays: number;

  /** Similarity threshold for deduplication */
  dedupThreshold: number;

  /** Enable contradiction detection */
  enableContradictionDetection: boolean;

  /** Database path for persistent storage */
  dbPath?: string;

  /** Vector dimension for embeddings */
  vectorDimension: number;

  /** Namespace for AgentDB storage */
  namespace: string;

  /** Enable AgentDB vector storage */
  enableAgentDB: boolean;
}

/**
 * Default ReasoningBank configuration
 */
const DEFAULT_CONFIG: ReasoningBankConfig = {
  maxTrajectories: 5000,
  distillationThreshold: 0.6,
  retrievalK: 3,
  mmrLambda: 0.7,
  maxPatternAgeDays: 30,
  dedupThreshold: 0.95,
  enableContradictionDetection: true,
  dbPath: undefined,
  vectorDimension: 768,
  namespace: 'reasoning-bank',
  enableAgentDB: true,
};

// ============================================================================
// Memory Types
// ============================================================================

/**
 * Memory entry with metadata
 */
interface MemoryEntry {
  memory: DistilledMemory;
  trajectory: Trajectory;
  verdict: TrajectoryVerdict;
  consolidated: boolean;
}

/**
 * Retrieval result with diversity scoring
 */
export interface RetrievalResult {
  memory: DistilledMemory;
  relevanceScore: number;
  diversityScore: number;
  combinedScore: number;
}

/**
 * Consolidation result
 */
export interface ConsolidationResult {
  removedDuplicates: number;
  contradictionsDetected: number;
  prunedPatterns: number;
  mergedPatterns: number;
}

/**
 * Step analysis result
 */
interface StepAnalysis {
  totalSteps: number;
  avgReward: number;
  positiveRatio: number;
  trajectory: number;
}

// ============================================================================
// ReasoningBank Class
// ============================================================================

/**
 * ReasoningBank - Trajectory storage and learning pipeline with AgentDB
 *
 * This class implements a complete learning pipeline for AI agents:
 * - Store and retrieve trajectories using vector similarity
 * - Judge trajectory quality using rule-based evaluation
 * - Distill successful trajectories into reusable patterns
 * - Consolidate patterns to remove duplicates and contradictions
 */
export class ReasoningBank {
  private config: ReasoningBankConfig;
  private trajectories: Map<string, Trajectory> = new Map();
  private memories: Map<string, MemoryEntry> = new Map();
  private patterns: Map<string, Pattern> = new Map();
  private eventListeners: Set<NeuralEventListener> = new Set();

  // AgentDB instance for vector storage
  private agentdb: any = null;
  private agentdbAvailable: boolean = false;
  private initialized: boolean = false;

  // Performance tracking
  private retrievalCount = 0;
  private totalRetrievalTime = 0;
  private distillationCount = 0;
  private totalDistillationTime = 0;
  private judgeCount = 0;
  private totalJudgeTime = 0;
  private consolidationCount = 0;
  private totalConsolidationTime = 0;
  // #1773 item 2 — observable retrieval-path counters so the dashboard can
  // tell users whether HNSW is actually firing or they're silently getting
  // brute-force performance.
  private hnswRetrievalCount = 0;
  private bruteForceRetrievalCount = 0;

  constructor(config: Partial<ReasoningBankConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  // ==========================================================================
  // Initialization
  // ==========================================================================

  /**
   * Initialize ReasoningBank with AgentDB
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;

    if (this.config.enableAgentDB) {
      await ensureAgentDBImport();
      this.agentdbAvailable = AgentDB !== undefined;

      if (this.agentdbAvailable) {
        try {
          this.agentdb = new AgentDB({
            dbPath: this.config.dbPath || ':memory:',
            namespace: this.config.namespace,
            vectorDimension: this.config.vectorDimension,
            vectorBackend: 'auto',
          });

          await this.agentdb.initialize();
          this.emitEvent({ type: 'memory_consolidated', memoriesCount: 0 });
        } catch (error) {
          console.warn('AgentDB initialization failed, using fallback:', error);
          this.agentdbAvailable = false;
        }
      }
    }

    this.initialized = true;
  }

  /**
   * Shutdown and cleanup resources
   */
  async shutdown(): Promise<void> {
    if (this.agentdb) {
      await this.agentdb.close?.();
    }
    this.initialized = false;
  }

  // ==========================================================================
  // STEP 1: RETRIEVE - Top-k memory injection with MMR diversity
  // ==========================================================================

  /**
   * Retrieve relevant memories using Maximal Marginal Relevance (MMR)
   *
   * Uses AgentDB HNSW index for 150x faster retrieval when available.
   *
   * @param queryEmbedding - Query vector for similarity search
   * @param k - Number of results to return (default: config.retrievalK)
   * @returns Retrieval results with relevance and diversity scores
   */
  async retrieve(queryEmbedding: Float32Array, k?: number): Promise<RetrievalResult[]> {
    const startTime = performance.now();
    const retrieveK = k ?? this.config.retrievalK;

    if (this.memories.size === 0) {
      return [];
    }

    let candidates: Array<{ entry: MemoryEntry; relevance: number }> = [];
    let usedHnsw = false;

    // Try AgentDB HNSW search first
    if (this.agentdb && this.agentdbAvailable) {
      try {
        const results = await this.searchWithAgentDB(queryEmbedding, retrieveK * 3);
        candidates = results
          .map(r => {
            const entry = this.memories.get(r.id);
            return entry ? { entry, relevance: r.similarity } : null;
          })
          .filter((c): c is { entry: MemoryEntry; relevance: number } => c !== null);
        if (candidates.length > 0) usedHnsw = true;
      } catch {
        // Fall through to brute-force
      }
    }

    // Fallback: brute-force search
    if (candidates.length === 0) {
      for (const entry of this.memories.values()) {
        const relevance = this.cosineSimilarity(queryEmbedding, entry.memory.embedding);
        candidates.push({ entry, relevance });
      }
      candidates.sort((a, b) => b.relevance - a.relevance);
    }

    // #1773 item 2 — record which retrieval path actually fired so the
    // dashboard can surface "you got HNSW" vs "you got O(n) brute-force"
    if (usedHnsw) this.hnswRetrievalCount++;
    else this.bruteForceRetrievalCount++;

    // Apply MMR for diversity
    const results: RetrievalResult[] = [];
    const selected: MemoryEntry[] = [];

    while (results.length < retrieveK && candidates.length > 0) {
      let bestIdx = 0;
      let bestScore = -Infinity;

      for (let i = 0; i < candidates.length; i++) {
        const candidate = candidates[i];

        // Compute MMR score: lambda * relevance - (1 - lambda) * max_similarity_to_selected
        const relevance = candidate.relevance;
        let maxSimilarity = 0;

        for (const sel of selected) {
          const sim = this.cosineSimilarity(
            candidate.entry.memory.embedding,
            sel.memory.embedding
          );
          maxSimilarity = Math.max(maxSimilarity, sim);
        }

        const diversityScore = 1 - maxSimilarity;
        const mmrScore = this.config.mmrLambda * relevance +
          (1 - this.config.mmrLambda) * diversityScore;

        if (mmrScore > bestScore) {
          bestScore = mmrScore;
          bestIdx = i;
        }
      }

      // Add best candidate
      const best = candidates[bestIdx];
      selected.push(best.entry);
      results.push({
        memory: best.entry.memory,
        relevanceScore: best.relevance,
        diversityScore: 1 - this.computeMaxSimilarity(best.entry, selected.slice(0, -1)),
        combinedScore: bestScore,
      });

      // Remove from candidates
      candidates.splice(bestIdx, 1);
    }

    // Update stats
    this.retrievalCount++;
    this.totalRetrievalTime += performance.now() - startTime;

    return results;
  }

  /**
   * Search for similar memories by content string
   *
   * @param content - Text content to search for
   * @param k - Number of results
   * @returns Retrieval results
   */
  async retrieveByContent(content: string, k?: number): Promise<RetrievalResult[]> {
    // Simple content-based retrieval using memory strategies
    const retrieveK = k ?? this.config.retrievalK;
    const results: RetrievalResult[] = [];

    const contentLower = content.toLowerCase();
    const entries = Array.from(this.memories.values());

    // Score by content similarity
    const scored = entries.map(entry => ({
      entry,
      score: this.computeContentSimilarity(contentLower, entry.memory.strategy),
    }));

    scored.sort((a, b) => b.score - a.score);

    for (let i = 0; i < Math.min(retrieveK, scored.length); i++) {
      const { entry, score } = scored[i];
      if (score > 0) {
        results.push({
          memory: entry.memory,
          relevanceScore: score,
          diversityScore: 1,
          combinedScore: score,
        });
      }
    }

    return results;
  }

  // ==========================================================================
  // STEP 2: JUDGE - LLM-as-judge trajectory evaluation
  // ==========================================================================

  /**
   * Judge a trajectory and produce a verdict
   *
   * Uses rule-based evaluation to assess trajectory quality.
   * In production, this could be enhanced with LLM-as-judge.
   *
   * @param trajectory - Completed trajectory to judge
   * @returns Verdict with success status and analysis
   */
  async judge(trajectory: Trajectory): Promise<TrajectoryVerdict> {
    const startTime = performance.now();

    if (!trajectory.isComplete) {
      throw new Error('Cannot judge incomplete trajectory');
    }

    // Analyze trajectory steps
    const stepAnalysis = this.analyzeSteps(trajectory.steps);

    // Compute success based on quality and step analysis
    const success = trajectory.qualityScore >= this.config.distillationThreshold &&
      stepAnalysis.positiveRatio > 0.6;

    // Identify strengths and weaknesses
    const strengths = this.identifyStrengths(trajectory, stepAnalysis);
    const weaknesses = this.identifyWeaknesses(trajectory, stepAnalysis);

    // Generate improvement suggestions
    const improvements = this.generateImprovements(weaknesses);

    // Compute relevance for similar future tasks
    const relevanceScore = this.computeRelevanceScore(trajectory);

    const verdict: TrajectoryVerdict = {
      success,
      confidence: this.computeConfidence(trajectory, stepAnalysis),
      strengths,
      weaknesses,
      improvements,
      relevanceScore,
    };

    // Store verdict with trajectory
    trajectory.verdict = verdict;

    // Update stats
    this.judgeCount++;
    this.totalJudgeTime += performance.now() - startTime;

    return verdict;
  }

  // ==========================================================================
  // STEP 3: DISTILL - Extract strategy memories from trajectories
  // ==========================================================================

  /**
   * Distill a trajectory into a reusable memory
   *
   * @param trajectory - Trajectory to distill
   * @returns Distilled memory or null if quality too low
   */
  async distill(trajectory: Trajectory): Promise<DistilledMemory | null> {
    const startTime = performance.now();

    // Must be judged first
    if (!trajectory.verdict) {
      await this.judge(trajectory);
    }

    // Only distill successful trajectories
    if (!trajectory.verdict!.success ||
        trajectory.qualityScore < this.config.distillationThreshold) {
      return null;
    }

    // Extract strategy from trajectory
    const strategy = this.extractStrategy(trajectory);

    // Extract key learnings
    const keyLearnings = this.extractKeyLearnings(trajectory);

    // Compute aggregated embedding
    const embedding = this.computeAggregateEmbedding(trajectory);

    const memory: DistilledMemory = {
      memoryId: `mem_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      trajectoryId: trajectory.trajectoryId,
      strategy,
      keyLearnings,
      embedding,
      quality: trajectory.qualityScore,
      usageCount: 0,
      lastUsed: Date.now(),
    };

    // Store the memory
    const entry: MemoryEntry = {
      memory,
      trajectory,
      verdict: trajectory.verdict!,
      consolidated: false,
    };
    this.memories.set(memory.memoryId, entry);

    // Store in AgentDB for vector search
    if (this.agentdb && this.agentdbAvailable) {
      await this.storeInAgentDB(memory);
    }

    // Also store trajectory reference
    trajectory.distilledMemory = memory;

    // Update stats
    this.distillationCount++;
    this.totalDistillationTime += performance.now() - startTime;

    this.emitEvent({
      type: 'trajectory_completed',
      trajectoryId: trajectory.trajectoryId,
      qualityScore: trajectory.qualityScore,
    });

    return memory;
  }

  /**
   * Batch distill multiple trajectories
   *
   * @param trajectories - Array of trajectories to distill
   * @returns Array of distilled memories (excludes nulls)
   */
  async distillBatch(trajectories: Trajectory[]): Promise<DistilledMemory[]> {
    const memories: DistilledMemory[] = [];

    for (const trajectory of trajectories) {
      const memory = await this.distill(trajectory);
      if (memory) {
        memories.push(memory);
      }
    }

    return memories;
  }

  // ==========================================================================
  // STEP 4: CONSOLIDATE - Dedup, detect contradictions, prune old patterns
  // ==========================================================================

  /**
   * Consolidate memories: deduplicate, detect contradictions, prune old
   *
   * @returns Consolidation statistics
   */
  async consolidate(): Promise<ConsolidationResult> {
    const startTime = performance.now();

    const result: ConsolidationResult = {
      removedDuplicates: 0,
      contradictionsDetected: 0,
      prunedPatterns: 0,
      mergedPatterns: 0,
    };

    // 1. Deduplicate similar memories
    result.removedDuplicates = await this.deduplicateMemories();

    // 2. Detect contradictions
    if (this.config.enableContradictionDetection) {
      result.contradictionsDetected = await this.detectContradictions();
    }

    // 3. Prune old patterns
    result.prunedPatterns = await this.pruneOldPatterns();

    // 4. Merge similar patterns
    result.mergedPatterns = await this.mergePatterns();

    // Update stats
    this.consolidationCount++;
    this.totalConsolidationTime += performance.now() - startTime;

    // Emit consolidation event
    this.emitEvent({
      type: 'memory_consolidated',
      memoriesCount: this.memories.size,
    });

    return result;
  }

  // ==========================================================================
  // Pattern Management
  // ==========================================================================

  /**
   * Convert a distilled memory to a pattern
   */
  memoryToPattern(memory: DistilledMemory): Pattern {
    const pattern: Pattern = {
      patternId: `pat_${memory.memoryId}`,
      name: this.generatePatternName(memory),
      domain: this.inferDomain(memory),
      embedding: memory.embedding,
      strategy: memory.strategy,
      successRate: memory.quality,
      usageCount: memory.usageCount,
      qualityHistory: [memory.quality],
      evolutionHistory: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };

    this.patterns.set(pattern.patternId, pattern);
    return pattern;
  }

  /**
   * Evolve a pattern based on new experience
   */
  evolvePattern(patternId: string, newExperience: Trajectory): void {
    const pattern = this.patterns.get(patternId);
    if (!pattern) return;

    const previousQuality = pattern.successRate;

    // Update quality history
    pattern.qualityHistory.push(newExperience.qualityScore);
    if (pattern.qualityHistory.length > 100) {
      pattern.qualityHistory = pattern.qualityHistory.slice(-100);
    }

    // Update success rate
    pattern.successRate = pattern.qualityHistory.reduce((a, b) => a + b, 0) /
      pattern.qualityHistory.length;

    pattern.usageCount++;
    pattern.updatedAt = Date.now();

    // Record evolution
    const evolutionType = this.determineEvolutionType(previousQuality, pattern.successRate);
    pattern.evolutionHistory.push({
      timestamp: Date.now(),
      type: evolutionType,
      previousQuality,
      newQuality: pattern.successRate,
      description: `Updated based on trajectory ${newExperience.trajectoryId}`,
    });

    // Emit event
    this.emitEvent({
      type: 'pattern_evolved',
      patternId,
      evolutionType,
    });
  }

  /**
   * Get all patterns
   */
  getPatterns(): Pattern[] {
    return Array.from(this.patterns.values());
  }

  /**
   * Find patterns matching a query
   */
  async findPatterns(queryEmbedding: Float32Array, k: number = 5): Promise<Pattern[]> {
    const results: Array<{ pattern: Pattern; score: number }> = [];

    for (const pattern of this.patterns.values()) {
      const score = this.cosineSimilarity(queryEmbedding, pattern.embedding);
      results.push({ pattern, score });
    }

    results.sort((a, b) => b.score - a.score);
    return results.slice(0, k).map(r => r.pattern);
  }

  // ==========================================================================
  // Trajectory Management
  // ==========================================================================

  /**
   * Store a trajectory
   */
  storeTrajectory(trajectory: Trajectory): void {
    this.trajectories.set(trajectory.trajectoryId, trajectory);

    // Prune if over capacity
    if (this.trajectories.size > this.config.maxTrajectories) {
      this.pruneTrajectories();
    }
  }

  /**
   * Get trajectory by ID
   */
  getTrajectory(trajectoryId: string): Trajectory | undefined {
    return this.trajectories.get(trajectoryId);
  }

  /**
   * Get all trajectories
   */
  getTrajectories(): Trajectory[] {
    return Array.from(this.trajectories.values());
  }

  /**
   * Get successful trajectories
   */
  getSuccessfulTrajectories(): Trajectory[] {
    return Array.from(this.trajectories.values())
      .filter(t => t.verdict?.success);
  }

  /**
   * Get failed trajectories
   */
  getFailedTrajectories(): Trajectory[] {
    return Array.from(this.trajectories.values())
      .filter(t => t.isComplete && !t.verdict?.success);
  }

  // ==========================================================================
  // Statistics
  // ==========================================================================

  /**
   * Get ReasoningBank statistics
   */
  getStats(): Record<string, number> {
    return {
      trajectoryCount: this.trajectories.size,
      memoryCount: this.memories.size,
      patternCount: this.patterns.size,
      avgRetrievalTimeMs: this.retrievalCount > 0
        ? this.totalRetrievalTime / this.retrievalCount
        : 0,
      avgDistillationTimeMs: this.distillationCount > 0
        ? this.totalDistillationTime / this.distillationCount
        : 0,
      avgJudgeTimeMs: this.judgeCount > 0
        ? this.totalJudgeTime / this.judgeCount
        : 0,
      avgConsolidationTimeMs: this.consolidationCount > 0
        ? this.totalConsolidationTime / this.consolidationCount
        : 0,
      consolidatedMemories: Array.from(this.memories.values())
        .filter(e => e.consolidated).length,
      successfulTrajectories: this.getSuccessfulTrajectories().length,
      failedTrajectories: this.getFailedTrajectories().length,
      agentdbEnabled: this.agentdbAvailable ? 1 : 0,
      retrievalCount: this.retrievalCount,
      // #1773 item 2 — observable retrieval-path split so callers can tell
      // whether they actually got HNSW or were silently downgraded.
      hnswRetrievalCount: this.hnswRetrievalCount,
      bruteForceRetrievalCount: this.bruteForceRetrievalCount,
      distillationCount: this.distillationCount,
      judgeCount: this.judgeCount,
      consolidationCount: this.consolidationCount,
    };
  }

  /**
   * Get detailed metrics for hooks
   */
  getDetailedMetrics(): {
    routing: { totalRoutes: number; avgConfidence: number; topAgents: Array<{ agent: string; count: number; successRate: number }> };
    edits: { totalEdits: number; successRate: number; commonPatterns: string[] };
    commands: { totalCommands: number; successRate: number; avgExecutionTime: number; commonCommands: string[] };
  } {
    const successfulTrajectories = this.getSuccessfulTrajectories();
    const allTrajectories = this.getTrajectories();
    const successRate = allTrajectories.length > 0
      ? successfulTrajectories.length / allTrajectories.length
      : 0;

    // Extract domain-based routing stats
    const domainStats = new Map<string, { count: number; successes: number }>();
    for (const t of allTrajectories) {
      const domain = t.domain || 'general';
      const stats = domainStats.get(domain) || { count: 0, successes: 0 };
      stats.count++;
      if (t.verdict?.success) stats.successes++;
      domainStats.set(domain, stats);
    }

    const topAgents = Array.from(domainStats.entries())
      .map(([agent, stats]) => ({
        agent,
        count: stats.count,
        successRate: stats.count > 0 ? stats.successes / stats.count : 0,
      }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 5);

    // Extract common patterns
    const patternStrategies = Array.from(this.patterns.values())
      .sort((a, b) => b.usageCount - a.usageCount)
      .slice(0, 5)
      .map(p => p.strategy);

    return {
      routing: {
        totalRoutes: allTrajectories.length,
        avgConfidence: successfulTrajectories.length > 0
          ? successfulTrajectories.reduce((sum, t) => sum + (t.verdict?.confidence || 0), 0) / successfulTrajectories.length
          : 0,
        topAgents,
      },
      edits: {
        totalEdits: this.memories.size,
        successRate,
        commonPatterns: patternStrategies.slice(0, 4),
      },
      commands: {
        totalCommands: this.distillationCount,
        successRate,
        avgExecutionTime: this.totalDistillationTime / Math.max(this.distillationCount, 1),
        commonCommands: patternStrategies.slice(0, 4),
      },
    };
  }

  // ==========================================================================
  // Persistence (#1773 Phase 1.6)
  // ==========================================================================

  /**
   * Serialize bank state to a JSON-safe object. Float32Array embeddings,
   * Maps, and nested structures encode losslessly. Excludes the AgentDB
   * connection (it's a runtime resource that must be re-acquired) and the
   * event listener Set (callers re-register on restore).
   */
  serialize(): unknown {
    return deepEncode({
      schemaVersion: 1,
      config: this.config,
      trajectories: this.trajectories,
      memories: this.memories,
      patterns: this.patterns,
      counters: {
        retrievalCount: this.retrievalCount,
        totalRetrievalTime: this.totalRetrievalTime,
        distillationCount: this.distillationCount,
        totalDistillationTime: this.totalDistillationTime,
        judgeCount: this.judgeCount,
        totalJudgeTime: this.totalJudgeTime,
        consolidationCount: this.consolidationCount,
        totalConsolidationTime: this.totalConsolidationTime,
      },
    });
  }

  /**
   * Restore bank state from a previously-serialized snapshot. AgentDB
   * connection is NOT restored — call initialize() again afterward to
   * re-acquire it. Event listeners are NOT restored — re-register manually.
   */
  deserialize(state: unknown): void {
    const decoded = deepDecode(state) as {
      schemaVersion: number;
      config: ReasoningBankConfig;
      trajectories: Map<string, Trajectory>;
      memories: Map<string, MemoryEntry>;
      patterns: Map<string, Pattern>;
      counters: {
        retrievalCount: number; totalRetrievalTime: number;
        distillationCount: number; totalDistillationTime: number;
        judgeCount: number; totalJudgeTime: number;
        consolidationCount: number; totalConsolidationTime: number;
      };
    };
    if (decoded.schemaVersion !== 1) {
      throw new Error(`ReasoningBank: unsupported schemaVersion ${decoded.schemaVersion} (expected 1)`);
    }
    this.config = { ...this.config, ...decoded.config };
    this.trajectories = decoded.trajectories;
    this.memories = decoded.memories;
    this.patterns = decoded.patterns;
    this.retrievalCount = decoded.counters.retrievalCount;
    this.totalRetrievalTime = decoded.counters.totalRetrievalTime;
    this.distillationCount = decoded.counters.distillationCount;
    this.totalDistillationTime = decoded.counters.totalDistillationTime;
    this.judgeCount = decoded.counters.judgeCount;
    this.totalJudgeTime = decoded.counters.totalJudgeTime;
    this.consolidationCount = decoded.counters.consolidationCount;
    this.totalConsolidationTime = decoded.counters.totalConsolidationTime;
  }

  // ==========================================================================
  // Event System
  // ==========================================================================

  addEventListener(listener: NeuralEventListener): void {
    this.eventListeners.add(listener);
  }

  removeEventListener(listener: NeuralEventListener): void {
    this.eventListeners.delete(listener);
  }

  private emitEvent(event: NeuralEvent): void {
    for (const listener of this.eventListeners) {
      try {
        listener(event);
      } catch (error) {
        console.error('Error in ReasoningBank event listener:', error);
      }
    }
  }

  // ==========================================================================
  // AgentDB Integration Helpers
  // ==========================================================================

  /**
   * Store memory in AgentDB for vector search
   */
  private async storeInAgentDB(memory: DistilledMemory): Promise<void> {
    if (!this.agentdb) return;

    try {
      if (typeof this.agentdb.store === 'function') {
        await this.agentdb.store(memory.memoryId, {
          content: memory.strategy,
          embedding: memory.embedding,
          metadata: {
            trajectoryId: memory.trajectoryId,
            quality: memory.quality,
            keyLearnings: memory.keyLearnings,
            usageCount: memory.usageCount,
            lastUsed: memory.lastUsed,
          },
        });
      }
    } catch (error) {
      console.warn('Failed to store in AgentDB:', error);
    }
  }

  /**
   * Search using AgentDB HNSW index
   */
  private async searchWithAgentDB(
    queryEmbedding: Float32Array,
    k: number
  ): Promise<Array<{ id: string; similarity: number }>> {
    if (!this.agentdb) return [];

    try {
      if (typeof this.agentdb.search === 'function') {
        return await this.agentdb.search(queryEmbedding, k);
      }

      // Try HNSW controller if available
      const hnsw = this.agentdb.getController?.('hnsw');
      if (hnsw) {
        const results = await hnsw.search(queryEmbedding, k);
        return results.map((r: any) => ({
          id: String(r.id),
          similarity: r.similarity || 1 - r.distance,
        }));
      }
    } catch {
      // Fall through to return empty
    }

    return [];
  }

  /**
   * Delete from AgentDB
   */
  private async deleteFromAgentDB(memoryId: string): Promise<void> {
    if (!this.agentdb) return;

    try {
      if (typeof this.agentdb.delete === 'function') {
        await this.agentdb.delete(memoryId);
      }
    } catch {
      // Ignore deletion errors
    }
  }

  // ==========================================================================
  // Private Helper Methods
  // ==========================================================================

  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
    if (a.length !== b.length) return 0;

    let dot = 0, normA = 0, normB = 0;
    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    const denom = Math.sqrt(normA) * Math.sqrt(normB);
    // Clamp to [0, 1] to handle floating point precision issues
    const similarity = denom > 0 ? dot / denom : 0;
    return Math.max(0, Math.min(1, similarity));
  }

  private computeContentSimilarity(query: string, content: string): number {
    const queryWords = new Set(query.toLowerCase().split(/\s+/));
    const contentWords = content.toLowerCase().split(/\s+/);

    let matches = 0;
    for (const word of contentWords) {
      if (queryWords.has(word)) matches++;
    }

    return contentWords.length > 0 ? matches / contentWords.length : 0;
  }

  private computeMaxSimilarity(entry: MemoryEntry, selected: MemoryEntry[]): number {
    let maxSim = 0;
    for (const sel of selected) {
      const sim = this.cosineSimilarity(entry.memory.embedding, sel.memory.embedding);
      maxSim = Math.max(maxSim, sim);
    }
    return maxSim;
  }

  private analyzeSteps(steps: TrajectoryStep[]): StepAnalysis {
    const rewardSum = steps.reduce((s, step) => s + step.reward, 0);
    const positiveSteps = steps.filter(s => s.reward > 0.5).length;

    return {
      totalSteps: steps.length,
      avgReward: steps.length > 0 ? rewardSum / steps.length : 0,
      positiveRatio: steps.length > 0 ? positiveSteps / steps.length : 0,
      trajectory: steps.length > 1
        ? (steps[steps.length - 1].reward - steps[0].reward)
        : 0,
    };
  }

  private identifyStrengths(trajectory: Trajectory, analysis: StepAnalysis): string[] {
    const strengths: string[] = [];

    if (analysis.avgReward > 0.7) {
      strengths.push('High average reward across steps');
    }
    if (analysis.trajectory > 0.2) {
      strengths.push('Positive reward trajectory');
    }
    if (trajectory.qualityScore > 0.8) {
      strengths.push('High overall quality');
    }
    if (analysis.totalSteps < 5 && trajectory.qualityScore > 0.6) {
      strengths.push('Efficient solution (few steps)');
    }

    return strengths;
  }

  private identifyWeaknesses(trajectory: Trajectory, analysis: StepAnalysis): string[] {
    const weaknesses: string[] = [];

    if (analysis.avgReward < 0.4) {
      weaknesses.push('Low average reward');
    }
    if (analysis.trajectory < -0.1) {
      weaknesses.push('Declining reward trajectory');
    }
    if (analysis.positiveRatio < 0.5) {
      weaknesses.push('Many negative/neutral steps');
    }
    if (analysis.totalSteps > 10 && trajectory.qualityScore < 0.7) {
      weaknesses.push('Long trajectory with mediocre outcome');
    }

    return weaknesses;
  }

  private generateImprovements(weaknesses: string[]): string[] {
    const improvements: string[] = [];

    for (const weakness of weaknesses) {
      if (weakness.includes('Low average reward')) {
        improvements.push('Consider alternative strategies for each step');
      }
      if (weakness.includes('Declining')) {
        improvements.push('Re-evaluate approach when reward decreases');
      }
      if (weakness.includes('negative/neutral')) {
        improvements.push('Focus on steps with clearer positive signals');
      }
      if (weakness.includes('Long trajectory')) {
        improvements.push('Look for shortcuts or more direct approaches');
      }
    }

    return improvements;
  }

  private computeRelevanceScore(trajectory: Trajectory): number {
    // Base relevance on quality and recency
    const qualityFactor = trajectory.qualityScore;
    const ageDays = (Date.now() - trajectory.startTime) / (1000 * 60 * 60 * 24);
    const recencyFactor = Math.exp(-ageDays / 30); // Decay over 30 days

    return qualityFactor * 0.7 + recencyFactor * 0.3;
  }

  private computeConfidence(trajectory: Trajectory, analysis: StepAnalysis): number {
    // More steps = more confidence
    const stepFactor = Math.min(analysis.totalSteps / 10, 1);
    // Consistent rewards = more confidence
    const consistencyFactor = analysis.positiveRatio;
    // Clear outcome = more confidence
    const outcomeFactor = Math.abs(trajectory.qualityScore - 0.5) * 2;

    return (stepFactor * 0.3 + consistencyFactor * 0.4 + outcomeFactor * 0.3);
  }

  private extractStrategy(trajectory: Trajectory): string {
    const actions = trajectory.steps.map(s => s.action);
    const uniqueActions = [...new Set(actions)];

    if (uniqueActions.length <= 3) {
      return `Apply ${uniqueActions.join(' -> ')}`;
    }

    return `Multi-step approach: ${uniqueActions.slice(0, 3).join(', ')}...`;
  }

  private extractKeyLearnings(trajectory: Trajectory): string[] {
    const learnings: string[] = [];
    const verdict = trajectory.verdict!;

    // Add key success factors
    if (verdict.success) {
      learnings.push(`Successful approach for ${trajectory.domain} domain`);
      for (const strength of verdict.strengths.slice(0, 2)) {
        learnings.push(`Strength: ${strength}`);
      }
    } else {
      learnings.push(`Approach needs refinement`);
      for (const improvement of verdict.improvements.slice(0, 2)) {
        learnings.push(`Improvement: ${improvement}`);
      }
    }

    return learnings;
  }

  private computeAggregateEmbedding(trajectory: Trajectory): Float32Array {
    if (trajectory.steps.length === 0) {
      return new Float32Array(this.config.vectorDimension);
    }

    const dim = trajectory.steps[0].stateAfter.length;
    const aggregate = new Float32Array(dim);

    // Weighted average of step embeddings (higher weight for later steps)
    let totalWeight = 0;
    for (let i = 0; i < trajectory.steps.length; i++) {
      const weight = (i + 1) / trajectory.steps.length;
      totalWeight += weight;
      const step = trajectory.steps[i];
      for (let j = 0; j < dim; j++) {
        aggregate[j] += step.stateAfter[j] * weight;
      }
    }

    // Normalize
    for (let j = 0; j < dim; j++) {
      aggregate[j] /= totalWeight;
    }

    return aggregate;
  }

  private async deduplicateMemories(): Promise<number> {
    let removed = 0;
    const entries = Array.from(this.memories.entries());

    for (let i = 0; i < entries.length; i++) {
      for (let j = i + 1; j < entries.length; j++) {
        const sim = this.cosineSimilarity(
          entries[i][1].memory.embedding,
          entries[j][1].memory.embedding
        );

        if (sim > this.config.dedupThreshold) {
          // Keep the higher quality one
          if (entries[i][1].memory.quality >= entries[j][1].memory.quality) {
            this.memories.delete(entries[j][0]);
            await this.deleteFromAgentDB(entries[j][0]);
          } else {
            this.memories.delete(entries[i][0]);
            await this.deleteFromAgentDB(entries[i][0]);
          }
          removed++;
        }
      }
    }

    return removed;
  }

  private async detectContradictions(): Promise<number> {
    let contradictions = 0;
    const entries = Array.from(this.memories.values());

    for (let i = 0; i < entries.length; i++) {
      for (let j = i + 1; j < entries.length; j++) {
        // Similar context but opposite outcomes
        const sim = this.cosineSimilarity(
          entries[i].memory.embedding,
          entries[j].memory.embedding
        );

        if (sim > 0.8) {
          const qualityDiff = Math.abs(
            entries[i].memory.quality - entries[j].memory.quality
          );

          if (qualityDiff > 0.4) {
            contradictions++;
            // Mark lower quality as consolidated (to exclude from retrieval)
            if (entries[i].memory.quality < entries[j].memory.quality) {
              entries[i].consolidated = true;
            } else {
              entries[j].consolidated = true;
            }
          }
        }
      }
    }

    return contradictions;
  }

  private async pruneOldPatterns(): Promise<number> {
    const now = Date.now();
    const maxAge = this.config.maxPatternAgeDays * 24 * 60 * 60 * 1000;
    let pruned = 0;

    for (const [id, pattern] of this.patterns) {
      const age = now - pattern.updatedAt;
      if (age > maxAge && pattern.usageCount < 5) {
        this.patterns.delete(id);
        pruned++;
      }
    }

    return pruned;
  }

  private async mergePatterns(): Promise<number> {
    let merged = 0;
    const patterns = Array.from(this.patterns.entries());

    for (let i = 0; i < patterns.length; i++) {
      for (let j = i + 1; j < patterns.length; j++) {
        const sim = this.cosineSimilarity(
          patterns[i][1].embedding,
          patterns[j][1].embedding
        );

        if (sim > 0.9 && patterns[i][1].domain === patterns[j][1].domain) {
          // Merge into higher quality pattern
          const [keepId, keep] = patterns[i][1].successRate >= patterns[j][1].successRate
            ? patterns[i]
            : patterns[j];
          const [removeId, remove] = patterns[i][1].successRate < patterns[j][1].successRate
            ? patterns[i]
            : patterns[j];

          // Combine statistics
          keep.usageCount += remove.usageCount;
          keep.qualityHistory.push(...remove.qualityHistory);
          keep.evolutionHistory.push({
            timestamp: Date.now(),
            type: 'merge',
            previousQuality: keep.successRate,
            newQuality: (keep.successRate + remove.successRate) / 2,
            description: `Merged with pattern ${removeId}`,
          });

          this.patterns.delete(removeId);
          merged++;
        }
      }
    }

    return merged;
  }

  private pruneTrajectories(): void {
    const entries = Array.from(this.trajectories.entries())
      .sort((a, b) => a[1].qualityScore - b[1].qualityScore);

    const toRemove = entries.length - Math.floor(this.config.maxTrajectories * 0.8);
    for (let i = 0; i < toRemove && i < entries.length; i++) {
      this.trajectories.delete(entries[i][0]);
    }
  }

  private generatePatternName(memory: DistilledMemory): string {
    const words = memory.strategy.split(' ').slice(0, 4);
    return words.join('_').toLowerCase().replace(/[^a-z0-9_]/g, '');
  }

  private inferDomain(memory: DistilledMemory): string {
    // First check if we have the trajectory directly in our store
    const trajectory = this.trajectories.get(memory.trajectoryId);
    if (trajectory?.domain) {
      return trajectory.domain;
    }

    // Check if the memory entry has the trajectory with domain info
    const memoryEntry = this.memories.get(memory.memoryId);
    if (memoryEntry?.trajectory?.domain) {
      return memoryEntry.trajectory.domain;
    }

    return 'general';
  }

  private determineEvolutionType(
    prev: number,
    curr: number
  ): 'improvement' | 'merge' | 'split' | 'prune' {
    const delta = curr - prev;
    if (delta > 0.05) return 'improvement';
    if (delta < -0.1) return 'prune';
    return 'improvement';
  }

  /**
   * Check if AgentDB is available and initialized
   */
  isAgentDBAvailable(): boolean {
    return this.agentdbAvailable;
  }
}

// ============================================================================
// Factory Function
// ============================================================================

/**
 * Factory function for creating ReasoningBank
 */
export function createReasoningBank(
  config?: Partial<ReasoningBankConfig>
): ReasoningBank {
  return new ReasoningBank(config);
}

/**
 * Create and initialize a ReasoningBank instance
 */
export async function createInitializedReasoningBank(
  config?: Partial<ReasoningBankConfig>
): Promise<ReasoningBank> {
  const bank = new ReasoningBank(config);
  await bank.initialize();
  return bank;
}

/**
 * V3 ReasoningBank Adapter
 *
 * Provides agentic-flow@alpha compatible ReasoningBank interface:
 * - 4-step pipeline: RETRIEVE, JUDGE, DISTILL, CONSOLIDATE
 * - Trajectory tracking and verdict judgment
 * - Memory distillation from successful trajectories
 * - Pattern consolidation with deduplication and pruning
 *
 * Based on Algorithm 3 & 4 from ReasoningBank paper.
 *
 * Performance Targets:
 * - Pattern retrieval: <5ms
 * - Verdict judgment: <10ms
 * - Memory distillation: <50ms
 * - Consolidation: <100ms
 */

import type {
  Trajectory,
  TrajectoryVerdict,
  DistilledMemory,
  Pattern,
  SONAMode,
} from './types.js';
import { createSONAManager, SONAManager } from './sona-manager.js';
import { createPatternLearner, PatternLearner } from './pattern-learner.js';

// ============================================================================
// ReasoningBank Types (agentic-flow compatible)
// ============================================================================

/**
 * ReasoningBank pattern record
 */
export interface ReasoningBankPattern {
  id: string;
  type: 'reasoning_memory' | 'strategy' | 'pattern';
  domain: string;
  patternData: {
    title: string;
    description: string;
    content: string;
    source: {
      taskId: string;
      agentId: string;
      outcome: 'Success' | 'Failure' | 'Partial';
      evidence: string[];
    };
    tags: string[];
    domain: string;
    createdAt: string;
    confidence: number;
    nUses: number;
  };
  confidence: number;
  usageCount: number;
  embedding: Float32Array;
  createdAt: number;
  lastUsed: number;
}

/**
 * Verdict from trajectory judgment
 */
export interface ReasoningBankVerdict {
  label: 'Success' | 'Failure' | 'Partial';
  score: number;
  evidence: string[];
  reasoning: string;
}

/**
 * Consolidation result
 */
export interface ConsolidationResult {
  itemsProcessed: number;
  duplicatesFound: number;
  contradictionsFound: number;
  itemsPruned: number;
  durationMs: number;
}

/**
 * ReasoningBank configuration
 */
export interface ReasoningBankConfig {
  /** Database path */
  dbPath?: string;

  /** Enable learning */
  enableLearning?: boolean;

  /** Enable reasoning agents */
  enableReasoning?: boolean;

  /** SONA mode */
  sonaMode?: SONAMode;

  /** Duplicate similarity threshold */
  duplicateThreshold?: number;

  /** Contradiction similarity threshold */
  contradictionThreshold?: number;

  /** Maximum age for pruning (days) */
  pruneAgeDays?: number;

  /** Minimum confidence to keep */
  minConfidenceKeep?: number;

  /** Consolidation trigger threshold */
  consolidateTriggerThreshold?: number;

  /** Maximum items for success distillation */
  maxItemsSuccess?: number;

  /** Maximum items for failure distillation */
  maxItemsFailure?: number;

  /** Confidence prior for success */
  confidencePriorSuccess?: number;

  /** Confidence prior for failure */
  confidencePriorFailure?: number;
}

// ============================================================================
// ReasoningBank Adapter Implementation
// ============================================================================

export class ReasoningBankAdapter {
  private readonly config: Required<ReasoningBankConfig>;
  private readonly sonaManager: SONAManager;
  private readonly patternLearner: PatternLearner;
  private patterns: Map<string, ReasoningBankPattern> = new Map();
  private newPatternsSinceConsolidation = 0;
  private initialized = false;

  constructor(config?: ReasoningBankConfig) {
    this.config = {
      dbPath: config?.dbPath || '.agentdb/reasoningbank.db',
      enableLearning: config?.enableLearning ?? true,
      enableReasoning: config?.enableReasoning ?? true,
      sonaMode: config?.sonaMode || 'balanced',
      duplicateThreshold: config?.duplicateThreshold ?? 0.95,
      contradictionThreshold: config?.contradictionThreshold ?? 0.85,
      pruneAgeDays: config?.pruneAgeDays ?? 30,
      minConfidenceKeep: config?.minConfidenceKeep ?? 0.3,
      consolidateTriggerThreshold: config?.consolidateTriggerThreshold ?? 100,
      maxItemsSuccess: config?.maxItemsSuccess ?? 5,
      maxItemsFailure: config?.maxItemsFailure ?? 3,
      confidencePriorSuccess: config?.confidencePriorSuccess ?? 0.8,
      confidencePriorFailure: config?.confidencePriorFailure ?? 0.5,
    };

    this.sonaManager = createSONAManager(this.config.sonaMode);
    this.patternLearner = createPatternLearner({
      maxPatterns: 5000,
      matchThreshold: 0.7,
      qualityThreshold: 0.5,
    });
  }

  async initialize(): Promise<void> {
    if (this.initialized) return;

    await this.sonaManager.initialize();
    this.initialized = true;
  }

  // ==========================================================================
  // Step 1: RETRIEVE - Top-k memory injection with MMR diversity
  // ==========================================================================

  /**
   * Retrieve relevant patterns for a query
   */
  async retrieve(
    queryEmbedding: Float32Array,
    options?: {
      k?: number;
      domain?: string;
      minConfidence?: number;
      useMmr?: boolean;
      mmrLambda?: number;
    }
  ): Promise<ReasoningBankPattern[]> {
    const k = options?.k ?? 5;
    const domain = options?.domain;
    const minConfidence = options?.minConfidence ?? 0;
    const useMmr = options?.useMmr ?? true;
    const mmrLambda = options?.mmrLambda ?? 0.7;

    // Get all patterns, filter by domain and confidence
    let candidates = Array.from(this.patterns.values());

    if (domain) {
      candidates = candidates.filter(p => p.domain === domain);
    }

    if (minConfidence > 0) {
      candidates = candidates.filter(p => p.confidence >= minConfidence);
    }

    if (candidates.length === 0) {
      return [];
    }

    // Compute similarities
    const similarities = candidates.map(pattern => ({
      pattern,
      similarity: this.cosineSimilarity(queryEmbedding, pattern.embedding),
    }));

    if (!useMmr) {
      // Simple top-k
      return similarities
        .sort((a, b) => b.similarity - a.similarity)
        .slice(0, k)
        .map(s => s.pattern);
    }

    // Maximal Marginal Relevance (MMR) for diversity
    return this.mmrSelect(queryEmbedding, similarities, k, mmrLambda);
  }

  // ==========================================================================
  // Step 2: JUDGE - LLM-as-judge trajectory evaluation
  // ==========================================================================

  /**
   * Judge a trajectory's success
   */
  async judge(trajectory: Trajectory): Promise<ReasoningBankVerdict> {
    // Compute quality metrics
    const qualityScore = trajectory.qualityScore;
    const stepCount = trajectory.steps.length;
    const avgReward = stepCount > 0
      ? trajectory.steps.reduce((sum, s) => sum + s.reward, 0) / stepCount
      : 0;

    // Determine verdict label
    let label: 'Success' | 'Failure' | 'Partial';
    if (qualityScore >= 0.8 && avgReward >= 0.7) {
      label = 'Success';
    } else if (qualityScore < 0.4 || avgReward < 0.3) {
      label = 'Failure';
    } else {
      label = 'Partial';
    }

    // Collect evidence
    const evidence: string[] = [];
    evidence.push(`Quality score: ${qualityScore.toFixed(2)}`);
    evidence.push(`Average reward: ${avgReward.toFixed(2)}`);
    evidence.push(`Step count: ${stepCount}`);

    if (trajectory.steps.length > 0) {
      const lastStep = trajectory.steps[trajectory.steps.length - 1];
      evidence.push(`Final action: ${lastStep.action}`);
      evidence.push(`Final reward: ${lastStep.reward.toFixed(2)}`);
    }

    // Generate reasoning
    const reasoning = this.generateJudgmentReasoning(trajectory, label, evidence);

    return {
      label,
      score: qualityScore,
      evidence,
      reasoning,
    };
  }

  // ==========================================================================
  // Step 3: DISTILL - Extract strategy memories from trajectories
  // ==========================================================================

  /**
   * Distill memories from a judged trajectory
   */
  async distill(
    trajectory: Trajectory,
    verdict: ReasoningBankVerdict,
    options?: {
      taskId?: string;
      agentId?: string;
    }
  ): Promise<string[]> {
    const maxItems = verdict.label === 'Success'
      ? this.config.maxItemsSuccess
      : this.config.maxItemsFailure;

    const confidencePrior = verdict.label === 'Success'
      ? this.config.confidencePriorSuccess
      : this.config.confidencePriorFailure;

    const memoryIds: string[] = [];

    // Extract key patterns from trajectory
    const patterns = this.extractPatternsFromTrajectory(trajectory, verdict);

    for (let i = 0; i < Math.min(patterns.length, maxItems); i++) {
      const pattern = patterns[i];

      const id = `mem_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;

      const rbPattern: ReasoningBankPattern = {
        id,
        type: 'reasoning_memory',
        domain: trajectory.domain,
        patternData: {
          title: pattern.title,
          description: pattern.description,
          content: pattern.content,
          source: {
            taskId: options?.taskId || trajectory.trajectoryId,
            agentId: options?.agentId || 'unknown',
            outcome: verdict.label,
            evidence: verdict.evidence,
          },
          tags: pattern.tags,
          domain: trajectory.domain,
          createdAt: new Date().toISOString(),
          confidence: confidencePrior,
          nUses: 0,
        },
        confidence: confidencePrior,
        usageCount: 0,
        embedding: this.computePatternEmbedding(trajectory, i),
        createdAt: Date.now(),
        lastUsed: Date.now(),
      };

      this.patterns.set(id, rbPattern);
      this.newPatternsSinceConsolidation++;
      memoryIds.push(id);
    }

    // Check if consolidation should run
    if (this.shouldConsolidate()) {
      await this.consolidate();
    }

    return memoryIds;
  }

  // ==========================================================================
  // Step 4: CONSOLIDATE - Dedup, detect contradictions, prune old patterns
  // ==========================================================================

  /**
   * Run consolidation: deduplicate, detect contradictions, prune
   */
  async consolidate(): Promise<ConsolidationResult> {
    const startTime = Date.now();

    const patterns = Array.from(this.patterns.values());
    let duplicatesFound = 0;
    let contradictionsFound = 0;
    let itemsPruned = 0;

    // Step 1: Deduplicate similar patterns
    const toRemove = new Set<string>();

    for (let i = 0; i < patterns.length; i++) {
      if (toRemove.has(patterns[i].id)) continue;

      for (let j = i + 1; j < patterns.length; j++) {
        if (toRemove.has(patterns[j].id)) continue;

        const similarity = this.cosineSimilarity(
          patterns[i].embedding,
          patterns[j].embedding
        );

        if (similarity >= this.config.duplicateThreshold) {
          duplicatesFound++;

          // Keep the one with higher usage/confidence
          const score1 = patterns[i].usageCount * patterns[i].confidence;
          const score2 = patterns[j].usageCount * patterns[j].confidence;

          if (score1 >= score2) {
            toRemove.add(patterns[j].id);
          } else {
            toRemove.add(patterns[i].id);
          }
        }
      }
    }

    // Step 2: Detect contradictions (similar embeddings, different outcomes)
    for (let i = 0; i < patterns.length; i++) {
      if (toRemove.has(patterns[i].id)) continue;

      for (let j = i + 1; j < patterns.length; j++) {
        if (toRemove.has(patterns[j].id)) continue;

        const similarity = this.cosineSimilarity(
          patterns[i].embedding,
          patterns[j].embedding
        );

        const outcome1 = patterns[i].patternData.source.outcome;
        const outcome2 = patterns[j].patternData.source.outcome;

        if (
          similarity >= this.config.contradictionThreshold &&
          outcome1 !== outcome2
        ) {
          contradictionsFound++;
          // Log contradiction for analysis (don't auto-remove)
          console.warn(`Contradiction detected: ${patterns[i].id} vs ${patterns[j].id}`);
        }
      }
    }

    // Step 3: Prune old, low-confidence patterns
    const now = Date.now();
    const maxAge = this.config.pruneAgeDays * 24 * 60 * 60 * 1000;

    for (const pattern of patterns) {
      if (toRemove.has(pattern.id)) continue;

      const age = now - pattern.createdAt;
      if (
        age > maxAge &&
        pattern.confidence < this.config.minConfidenceKeep &&
        pattern.usageCount < 3
      ) {
        toRemove.add(pattern.id);
        itemsPruned++;
      }
    }

    // Remove marked patterns
    for (const id of toRemove) {
      this.patterns.delete(id);
    }

    this.newPatternsSinceConsolidation = 0;
    const durationMs = Date.now() - startTime;

    return {
      itemsProcessed: patterns.length,
      duplicatesFound,
      contradictionsFound,
      itemsPruned,
      durationMs,
    };
  }

  // ==========================================================================
  // Pattern Management
  // ==========================================================================

  /**
   * Insert a pattern directly
   */
  insertPattern(pattern: Omit<ReasoningBankPattern, 'createdAt' | 'lastUsed'>): string {
    const fullPattern: ReasoningBankPattern = {
      ...pattern,
      createdAt: Date.now(),
      lastUsed: Date.now(),
    };

    this.patterns.set(pattern.id, fullPattern);
    this.newPatternsSinceConsolidation++;

    return pattern.id;
  }

  /**
   * Get a pattern by ID
   */
  getPattern(id: string): ReasoningBankPattern | undefined {
    const pattern = this.patterns.get(id);
    if (pattern) {
      pattern.lastUsed = Date.now();
      pattern.usageCount++;
    }
    return pattern;
  }

  /**
   * Update pattern confidence
   */
  updateConfidence(id: string, delta: number): void {
    const pattern = this.patterns.get(id);
    if (pattern) {
      pattern.confidence = Math.max(0, Math.min(1, pattern.confidence + delta));
      pattern.patternData.confidence = pattern.confidence;
    }
  }

  /**
   * Get statistics
   */
  getStats(): {
    totalPatterns: number;
    byDomain: Record<string, number>;
    byOutcome: Record<string, number>;
    avgConfidence: number;
  } {
    const patterns = Array.from(this.patterns.values());
    const byDomain: Record<string, number> = {};
    const byOutcome: Record<string, number> = {};

    for (const pattern of patterns) {
      byDomain[pattern.domain] = (byDomain[pattern.domain] || 0) + 1;
      byOutcome[pattern.patternData.source.outcome] =
        (byOutcome[pattern.patternData.source.outcome] || 0) + 1;
    }

    const avgConfidence = patterns.length > 0
      ? patterns.reduce((sum, p) => sum + p.confidence, 0) / patterns.length
      : 0;

    return {
      totalPatterns: patterns.length,
      byDomain,
      byOutcome,
      avgConfidence,
    };
  }

  // ==========================================================================
  // Private Helper Methods
  // ==========================================================================

  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
    if (a.length !== b.length) return 0;

    let dot = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    const denom = Math.sqrt(normA) * Math.sqrt(normB);
    return denom > 0 ? dot / denom : 0;
  }

  private mmrSelect(
    query: Float32Array,
    candidates: Array<{ pattern: ReasoningBankPattern; similarity: number }>,
    k: number,
    lambda: number
  ): ReasoningBankPattern[] {
    const selected: ReasoningBankPattern[] = [];
    const remaining = [...candidates];

    while (selected.length < k && remaining.length > 0) {
      let bestScore = -Infinity;
      let bestIdx = 0;

      for (let i = 0; i < remaining.length; i++) {
        const candidate = remaining[i];
        const relevance = candidate.similarity;

        // Calculate max similarity to already selected patterns
        let maxSimilarity = 0;
        for (const sel of selected) {
          const sim = this.cosineSimilarity(candidate.pattern.embedding, sel.embedding);
          maxSimilarity = Math.max(maxSimilarity, sim);
        }

        // MMR score: lambda * relevance - (1 - lambda) * redundancy
        const score = lambda * relevance - (1 - lambda) * maxSimilarity;

        if (score > bestScore) {
          bestScore = score;
          bestIdx = i;
        }
      }

      selected.push(remaining[bestIdx].pattern);
      remaining.splice(bestIdx, 1);
    }

    return selected;
  }

  private shouldConsolidate(): boolean {
    return this.newPatternsSinceConsolidation >= this.config.consolidateTriggerThreshold;
  }

  private generateJudgmentReasoning(
    trajectory: Trajectory,
    label: string,
    evidence: string[]
  ): string {
    const parts: string[] = [];

    parts.push(`Trajectory ${trajectory.trajectoryId} judged as ${label}.`);
    parts.push(`Domain: ${trajectory.domain}, Steps: ${trajectory.steps.length}.`);

    if (label === 'Success') {
      parts.push('The trajectory achieved high quality scores with positive rewards.');
    } else if (label === 'Failure') {
      parts.push('The trajectory had low quality scores or negative rewards.');
    } else {
      parts.push('The trajectory showed mixed results with room for improvement.');
    }

    return parts.join(' ');
  }

  private extractPatternsFromTrajectory(
    trajectory: Trajectory,
    verdict: ReasoningBankVerdict
  ): Array<{ title: string; description: string; content: string; tags: string[] }> {
    const patterns: Array<{ title: string; description: string; content: string; tags: string[] }> = [];

    // Extract overall strategy pattern
    const actions = trajectory.steps.map(s => s.action);
    patterns.push({
      title: `${verdict.label}: ${trajectory.context.slice(0, 50)}`,
      description: `Strategy for ${trajectory.domain} task with ${verdict.label.toLowerCase()} outcome`,
      content: `Actions: ${actions.slice(0, 5).join(' -> ')}${actions.length > 5 ? '...' : ''}`,
      tags: [verdict.label.toLowerCase(), trajectory.domain, 'strategy'],
    });

    // Extract key step patterns for successful trajectories
    if (verdict.label === 'Success' && trajectory.steps.length > 0) {
      const highRewardSteps = trajectory.steps
        .filter(s => s.reward > 0.7)
        .slice(0, 3);

      for (const step of highRewardSteps) {
        patterns.push({
          title: `High-reward action: ${step.action.slice(0, 30)}`,
          description: `Effective action in ${trajectory.domain} context`,
          content: `Action: ${step.action}, Reward: ${step.reward.toFixed(2)}`,
          tags: ['high-reward', trajectory.domain, 'action'],
        });
      }
    }

    return patterns;
  }

  private computePatternEmbedding(trajectory: Trajectory, index: number): Float32Array {
    if (trajectory.steps.length === 0) {
      return new Float32Array(768);
    }

    // Use weighted average of step embeddings
    const dim = trajectory.steps[0].stateAfter.length;
    const embedding = new Float32Array(dim);

    let totalWeight = 0;
    for (let i = 0; i < trajectory.steps.length; i++) {
      const weight = (i + 1 + index) / (trajectory.steps.length + index);
      totalWeight += weight;
      for (let j = 0; j < dim; j++) {
        embedding[j] += trajectory.steps[i].stateAfter[j] * weight;
      }
    }

    for (let j = 0; j < dim; j++) {
      embedding[j] /= totalWeight;
    }

    return embedding;
  }
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create ReasoningBank adapter
 */
export function createReasoningBankAdapter(
  config?: ReasoningBankConfig
): ReasoningBankAdapter {
  return new ReasoningBankAdapter(config);
}

/**
 * Create default ReasoningBank adapter
 */
export function createDefaultReasoningBankAdapter(): ReasoningBankAdapter {
  return new ReasoningBankAdapter({
    enableLearning: true,
    enableReasoning: true,
    sonaMode: 'balanced',
  });
}

/**
 * SONA Integration for V3 Neural Module
 *
 * Wraps @ruvector/sona package for V3 usage with:
 * - Trajectory tracking and verdict judgment
 * - Pattern extraction and memory distillation
 * - Sub-0.05ms learning performance target
 * - Clean TypeScript API with proper types
 *
 * @module sona-integration
 */

import { SonaEngine, type JsSonaConfig, type JsLearnedPattern } from '@ruvector/sona';
import type {
  Trajectory,
  TrajectoryStep,
  TrajectoryVerdict,
  DistilledMemory,
  SONAMode,
  SONAModeConfig,
} from './types.js';

// =============================================================================
// Types
// =============================================================================

/**
 * Context for SONA learning adaptation
 */
export interface Context {
  /** Task domain */
  domain: 'code' | 'creative' | 'reasoning' | 'chat' | 'math' | 'general';
  /** Current query embedding */
  queryEmbedding: Float32Array;
  /** Additional context metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Adapted behavior result from SONA
 */
export interface AdaptedBehavior {
  /** Transformed query embedding after micro-LoRA */
  transformedQuery: Float32Array;
  /** Similar learned patterns */
  patterns: JsLearnedPattern[];
  /** Suggested route/model */
  suggestedRoute?: string;
  /** Confidence score */
  confidence: number;
}

/**
 * SONA engine statistics
 */
export interface SONAStats {
  /** Total trajectories recorded */
  totalTrajectories: number;
  /** Patterns learned */
  patternsLearned: number;
  /** Average quality */
  avgQuality: number;
  /** Last learning time (ms) */
  lastLearningMs: number;
  /** Engine enabled state */
  enabled: boolean;
}

// =============================================================================
// Mode Configuration Mapping
// =============================================================================

/**
 * Convert V3 SONA mode to @ruvector/sona config
 */
function modeToConfig(mode: SONAMode, modeConfig: SONAModeConfig): JsSonaConfig {
  const baseConfig: JsSonaConfig = {
    hiddenDim: 768, // Standard transformer dimension
    embeddingDim: 768,
    microLoraRank: modeConfig.loraRank <= 2 ? modeConfig.loraRank : 1,
    baseLoraRank: modeConfig.loraRank,
    microLoraLr: modeConfig.learningRate,
    baseLoraLr: modeConfig.learningRate * 0.1,
    ewcLambda: modeConfig.ewcLambda,
    patternClusters: modeConfig.patternClusters,
    trajectoryCapacity: modeConfig.trajectoryCapacity,
    qualityThreshold: modeConfig.qualityThreshold,
    enableSimd: true,
  };

  // Mode-specific adjustments
  switch (mode) {
    case 'real-time':
      return {
        ...baseConfig,
        microLoraRank: 1,
        backgroundIntervalMs: 60000, // 1 minute
      };
    case 'edge':
      return {
        ...baseConfig,
        hiddenDim: 384, // Smaller for edge devices
        embeddingDim: 384,
        microLoraRank: 1,
        patternClusters: 25,
        backgroundIntervalMs: 300000, // 5 minutes
      };
    case 'research':
      return {
        ...baseConfig,
        baseLoraRank: 16,
        backgroundIntervalMs: 3600000, // 1 hour
      };
    case 'batch':
      return {
        ...baseConfig,
        backgroundIntervalMs: 7200000, // 2 hours
      };
    case 'balanced':
    default:
      return {
        ...baseConfig,
        backgroundIntervalMs: 1800000, // 30 minutes
      };
  }
}

// =============================================================================
// SONA Learning Engine
// =============================================================================

/**
 * SONA Learning Engine - wraps @ruvector/sona for V3 usage
 *
 * Performance targets:
 * - learn(): <0.05ms
 * - adapt(): <0.1ms
 * - Full learning cycle: <10ms
 */
export class SONALearningEngine {
  private engine: SonaEngine;
  private trajectoryMap: Map<string, number> = new Map();
  private adaptationTimeMs: number = 0;
  private learningTimeMs: number = 0;
  private mode: SONAMode;
  private modeConfig: SONAModeConfig;

  constructor(mode: SONAMode, modeConfig: SONAModeConfig) {
    this.mode = mode;
    this.modeConfig = modeConfig;
    const config = modeToConfig(mode, modeConfig);
    this.engine = SonaEngine.withConfig(config);
  }

  /**
   * Learn from a trajectory
   *
   * Performance target: <0.05ms
   *
   * @param trajectory - Trajectory to learn from
   */
  async learn(trajectory: Trajectory): Promise<void> {
    const startTime = performance.now();

    try {
      // Begin trajectory recording
      const queryEmbedding = this.trajectoryToQueryEmbedding(trajectory);
      const trajectoryId = this.engine.beginTrajectory(
        Array.from(queryEmbedding)
      );

      // Add trajectory steps
      for (const step of trajectory.steps) {
        const activations = this.stateToActivations(step.stateBefore);
        const attentionWeights = this.stateToAttentionWeights(step.stateAfter);

        this.engine.addTrajectoryStep(
          trajectoryId,
          Array.from(activations),
          Array.from(attentionWeights),
          step.reward
        );
      }

      // Set context if available
      if (trajectory.domain) {
        this.engine.addTrajectoryContext(trajectoryId, trajectory.domain);
      }

      // Complete trajectory with quality score
      const quality = this.calculateQuality(trajectory);
      this.engine.endTrajectory(trajectoryId, quality);

      // Flush instant updates
      this.engine.flush();

      this.learningTimeMs = performance.now() - startTime;
    } catch (error) {
      throw new Error(`SONA learning failed: ${error}`);
    }
  }

  /**
   * Adapt behavior based on context
   *
   * @param context - Current context for adaptation
   * @returns Adapted behavior with transformed embeddings
   */
  async adapt(context: Context): Promise<AdaptedBehavior> {
    const startTime = performance.now();

    try {
      // Apply micro-LoRA transformation
      const transformedQuery = this.engine.applyMicroLora(
        Array.from(context.queryEmbedding)
      );

      // Find similar patterns
      const patterns = this.engine.findPatterns(
        Array.from(context.queryEmbedding),
        5
      );

      // Determine suggested route from patterns
      const suggestedRoute = this.inferRoute(patterns, context);
      const confidence = patterns.length > 0 ? patterns[0].avgQuality : 0.5;

      this.adaptationTimeMs = performance.now() - startTime;

      return {
        transformedQuery: new Float32Array(transformedQuery),
        patterns,
        suggestedRoute,
        confidence,
      };
    } catch (error) {
      throw new Error(`SONA adaptation failed: ${error}`);
    }
  }

  /**
   * Get last adaptation time
   *
   * @returns Adaptation time in milliseconds
   */
  getAdaptationTime(): number {
    return this.adaptationTimeMs;
  }

  /**
   * Get last learning time
   *
   * @returns Learning time in milliseconds
   */
  getLearningTime(): number {
    return this.learningTimeMs;
  }

  /**
   * Reset learning state
   */
  resetLearning(): void {
    // Create a new engine with the same config
    const config = modeToConfig(this.mode, this.modeConfig);
    this.engine = SonaEngine.withConfig(config);
    this.trajectoryMap.clear();
    this.adaptationTimeMs = 0;
    this.learningTimeMs = 0;
  }

  /**
   * Force immediate learning cycle
   *
   * @returns Status message
   */
  forceLearning(): string {
    return this.engine.forceLearn();
  }

  /**
   * Tick background learning (call periodically)
   *
   * @returns Status message if learning occurred
   */
  tick(): string | null {
    return this.engine.tick();
  }

  /**
   * Get engine statistics
   *
   * @returns SONA engine statistics
   */
  getStats(): SONAStats {
    const statsJson = this.engine.getStats();
    const stats = JSON.parse(statsJson);

    return {
      totalTrajectories: stats.total_trajectories || 0,
      patternsLearned: stats.patterns_learned || 0,
      avgQuality: stats.avg_quality || 0,
      lastLearningMs: this.learningTimeMs,
      enabled: this.engine.isEnabled(),
    };
  }

  /**
   * Enable or disable the engine
   *
   * @param enabled - Whether to enable the engine
   */
  setEnabled(enabled: boolean): void {
    this.engine.setEnabled(enabled);
  }

  /**
   * Check if engine is enabled
   *
   * @returns Whether the engine is enabled
   */
  isEnabled(): boolean {
    return this.engine.isEnabled();
  }

  /**
   * Find learned patterns similar to query
   *
   * @param queryEmbedding - Query embedding
   * @param k - Number of patterns to return
   * @returns Learned patterns
   */
  findPatterns(queryEmbedding: Float32Array, k: number = 5): JsLearnedPattern[] {
    return this.engine.findPatterns(Array.from(queryEmbedding), k);
  }

  // =============================================================================
  // Private Helpers
  // =============================================================================

  /**
   * Convert trajectory to query embedding
   */
  private trajectoryToQueryEmbedding(trajectory: Trajectory): Float32Array {
    // Use the first step's state as query
    if (trajectory.steps.length > 0) {
      return trajectory.steps[0].stateBefore;
    }
    // Fallback to zero embedding
    return new Float32Array(768);
  }

  /**
   * Convert state embedding to activations
   */
  private stateToActivations(state: Float32Array): Float32Array {
    // For now, use state directly as activations
    // In a real implementation, this would extract layer activations
    return state;
  }

  /**
   * Convert state embedding to attention weights
   */
  private stateToAttentionWeights(state: Float32Array): Float32Array {
    // For now, use normalized state as attention weights
    // In a real implementation, this would extract attention patterns
    const sum = state.reduce((acc, val) => acc + Math.abs(val), 0);
    if (sum === 0) return state;

    const weights = new Float32Array(state.length);
    for (let i = 0; i < state.length; i++) {
      weights[i] = Math.abs(state[i]) / sum;
    }
    return weights;
  }

  /**
   * Calculate quality score for trajectory
   */
  private calculateQuality(trajectory: Trajectory): number {
    if (trajectory.qualityScore !== undefined) {
      return trajectory.qualityScore;
    }

    // Calculate from steps
    if (trajectory.steps.length === 0) return 0.5;

    const avgReward = trajectory.steps.reduce((sum, step) => sum + step.reward, 0) /
                      trajectory.steps.length;

    // Normalize to [0, 1]
    return Math.max(0, Math.min(1, (avgReward + 1) / 2));
  }

  /**
   * Infer suggested route from patterns and context
   */
  private inferRoute(patterns: JsLearnedPattern[], context: Context): string | undefined {
    if (patterns.length === 0) return undefined;

    // Use the highest quality pattern's type as route
    const bestPattern = patterns.reduce((best, pattern) =>
      pattern.avgQuality > best.avgQuality ? pattern : best
    );

    return bestPattern.patternType || `${context.domain}-default`;
  }
}

