/**
 * Seedable PRNG for reproducible training.
 *
 * The package previously used `Math.random()` everywhere — fast but
 * non-deterministic, which breaks reproducible training, A/B mode comparison,
 * and unit tests that assert on stochastic behavior.
 *
 * This module exposes a Mulberry32-based PRNG (small, fast, statistically
 * sound for non-cryptographic use) plus a global injection point. RL
 * algorithms, weight initialization, and exploration policies should call
 * `random()` / `randomInt()` / `randomNormal()` from here instead of
 * `Math.random()` directly.
 *
 * For deterministic runs:
 *
 *   import { setGlobalRng, Mulberry32 } from '@claude-flow/neural';
 *   setGlobalRng(new Mulberry32(42));
 *
 * After that, all `random()` consumers produce the same sequence on
 * every run. Pass a different seed to vary the trajectory.
 */

export interface RNG {
  /** Uniform sample in [0, 1) */
  next(): number;
  /** Integer sample in [min, max) */
  nextInt(min: number, max: number): number;
  /** Standard normal sample (Box-Muller) */
  nextNormal(): number;
  /** Reseed in place (mutates this instance) */
  seed(s: number): void;
}

/**
 * Mulberry32 — 32-bit chaotic-state PRNG. Period 2^32, passes BigCrush
 * subtests, ~5x faster than seedrandom. Not cryptographically secure.
 */
export class Mulberry32 implements RNG {
  private state: number;

  constructor(seedValue?: number) {
    // Default to a time-based non-deterministic seed; explicit 0 stays 0
    // (the user might want deterministically empty state).
    this.state = (seedValue !== undefined ? seedValue : Date.now() & 0x7fffffff) | 0;
  }

  next(): number {
    this.state = (this.state + 0x6d2b79f5) | 0;
    let t = Math.imul(this.state ^ (this.state >>> 15), 1 | this.state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  nextInt(min: number, max: number): number {
    return min + Math.floor(this.next() * (max - min));
  }

  nextNormal(): number {
    // Box-Muller transform — generates a standard normal sample (mean 0, var 1)
    const u1 = this.next() || 1e-12; // avoid log(0)
    const u2 = this.next();
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  }

  seed(s: number): void {
    this.state = s | 0;
  }
}

/**
 * Math.random()-backed RNG for backward compatibility / production default.
 * Fast, non-deterministic, what the package shipped with before.
 */
export class MathRandomRng implements RNG {
  next(): number {
    return Math.random();
  }
  nextInt(min: number, max: number): number {
    return min + Math.floor(Math.random() * (max - min));
  }
  nextNormal(): number {
    const u1 = Math.random() || 1e-12;
    const u2 = Math.random();
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  }
  seed(_s: number): void {
    // no-op — Math.random isn't seedable
  }
}

let globalRng: RNG = new MathRandomRng();

/**
 * Replace the global RNG. Pass a `Mulberry32(seed)` for reproducible runs,
 * or any custom RNG impl for testing. Idempotent.
 */
export function setGlobalRng(rng: RNG): void {
  globalRng = rng;
}

/** Get the current global RNG (mainly for tests/diagnostics). */
export function getGlobalRng(): RNG {
  return globalRng;
}

/** Reset to the default `Math.random()`-backed RNG. Mainly for tests. */
export function resetGlobalRng(): void {
  globalRng = new MathRandomRng();
}

/** Convenience: uniform sample in [0, 1) using the global RNG. */
export function random(): number {
  return globalRng.next();
}

/** Convenience: integer sample in [min, max) using the global RNG. */
export function randomInt(min: number, max: number): number {
  return globalRng.nextInt(min, max);
}

/** Convenience: standard normal sample using the global RNG. */
export function randomNormal(): number {
  return globalRng.nextNormal();
}

/**
 * Self-consistency orchestrator (Wang et al. 2022, "Self-Consistency Improves
 * Chain of Thought Reasoning in Language Models").
 *
 * Runs an arbitrary stochastic operation N times and aggregates the results.
 * Reduces variance from single-shot stochastic predictions; on reasoning
 * benchmarks the technique typically gains 5–15pp accuracy at the cost of
 * Nx compute. The package's RL algorithms, pattern matching, and routing
 * all benefit since they sample randomly and can produce different outputs
 * across calls.
 *
 * Aggregators:
 *   - 'majority': pick the most common output (for discrete answers / labels).
 *                 Uses JSON.stringify for grouping; stable for primitive and
 *                 plain-object outputs. Float32Array values aggregate via
 *                 their array-form encoding.
 *   - 'mean':     numeric average (operation must return number).
 *                 Agreement = 1 - normalized stddev.
 *   - 'first':    take the first sample (no aggregation; useful for testing
 *                 or deterministic ops).
 *
 * Pair with `setGlobalRng(new Mulberry32(seed))` to make a self-consistency
 * run reproducible across machines.
 */

import type { RNG } from './rng.js';
import { random } from './rng.js';

export type SelfConsistencyAggregator = 'majority' | 'mean' | 'first';

export interface SelfConsistencyConfig {
  /** Number of samples to draw. Required. Larger N = more stable, more compute. */
  N: number;
  /** How to aggregate samples into a single answer. Default: 'majority'. */
  aggregator?: SelfConsistencyAggregator;
  /**
   * Optional RNG to advance per sample (e.g. to differentiate seeds across
   * samples when the operation reads from the global RNG). The orchestrator
   * itself doesn't directly call this RNG; it's provided so callers can
   * thread per-sample state (e.g. by reseeding before each call).
   */
  rng?: RNG;
}

export interface SelfConsistencyResult<T> {
  /** The aggregated answer (majority vote, mean, or first). */
  finalAnswer: T;
  /** Every sample produced, in the order produced. Length === config.N. */
  samples: T[];
  /**
   * For 'majority': fraction of samples matching finalAnswer (0..1).
   * For 'mean':    1 - normalized stddev (rough confidence proxy).
   * For 'first':   always 1.
   */
  agreement: number;
  /** The config used for this run. */
  config: SelfConsistencyConfig;
}

/**
 * Run an operation N times and aggregate. The operation is awaited
 * sequentially — if the caller wants concurrency they can wrap it themselves.
 */
export async function selfConsistency<T>(
  operation: () => Promise<T> | T,
  config: SelfConsistencyConfig,
): Promise<SelfConsistencyResult<T>> {
  if (!Number.isInteger(config.N) || config.N <= 0) {
    throw new Error(`selfConsistency: N must be a positive integer, got ${config.N}`);
  }

  const samples: T[] = [];
  for (let i = 0; i < config.N; i++) {
    samples.push(await operation());
  }

  const aggregator: SelfConsistencyAggregator = config.aggregator ?? 'majority';

  let finalAnswer: T;
  let agreement: number;

  if (aggregator === 'majority') {
    // Group by JSON-stringified value (handles primitives, plain objects,
    // arrays). Float32Array does NOT JSON-encode losslessly by default —
    // callers wanting f32 majority should pre-convert via Array.from.
    const counts = new Map<string, { value: T; count: number }>();
    for (const s of samples) {
      const key = canonicalKey(s);
      const existing = counts.get(key);
      if (existing) existing.count += 1;
      else counts.set(key, { value: s, count: 1 });
    }
    let best: { value: T; count: number } = { value: samples[0], count: 0 };
    for (const c of counts.values()) {
      if (c.count > best.count) best = c;
    }
    finalAnswer = best.value;
    agreement = best.count / samples.length;
  } else if (aggregator === 'mean') {
    const nums = samples as unknown as number[];
    if (!nums.every((v) => typeof v === 'number' && Number.isFinite(v))) {
      throw new Error("selfConsistency: aggregator='mean' requires every sample to be a finite number");
    }
    const mean = nums.reduce((a, b) => a + b, 0) / nums.length;
    const variance = nums.reduce((s, v) => s + (v - mean) ** 2, 0) / nums.length;
    const stddev = Math.sqrt(variance);
    const range = Math.max(1e-9, Math.abs(mean) || 1); // avoid div-by-0
    finalAnswer = mean as unknown as T;
    agreement = Math.max(0, Math.min(1, 1 - stddev / range));
  } else {
    finalAnswer = samples[0];
    agreement = 1;
  }

  return { finalAnswer, samples, agreement, config };
}

/**
 * Canonical-form key for grouping. JSON.stringify is enough for primitives,
 * arrays, and plain objects with stable key order. Callers wanting locale-
 * insensitive or shape-aware aggregation should pre-canonicalize their
 * outputs before calling selfConsistency.
 */
function canonicalKey(v: unknown): string {
  try {
    return JSON.stringify(v);
  } catch {
    // Cyclic structures, BigInt, etc.
    return String(v);
  }
}

// Re-export for callers that need it
export { random };

/**
 * JSON-safe serialization helpers for neural state.
 *
 * The package's hot-path types use `Float32Array` and `Map<string, X>` which
 * don't survive `JSON.stringify` cleanly. These helpers encode/decode them
 * in a stable shape so SONAManager / ReasoningBank / PatternLearner can
 * round-trip through `serialize()` → `JSON.stringify` → file → `JSON.parse`
 * → `deserialize()` without losing precision or structure.
 *
 * Encoding:
 *   Float32Array  ↔ { __f32: number[] }
 *   Map<K, V>     ↔ { __map: Array<[K, V]> }
 *
 * Numbers in Float32Array are stored as plain JS `number` (double precision).
 * Round-trip is loss-free at single-precision (the values were f32 originally;
 * widening to f64 then narrowing back is exact for any finite f32).
 */

export interface EncodedFloat32Array {
  __f32: number[];
}

export interface EncodedMap<V> {
  __map: Array<[string, V]>;
}

export function encodeFloat32Array(arr: Float32Array): EncodedFloat32Array {
  return { __f32: Array.from(arr) };
}

export function decodeFloat32Array(encoded: EncodedFloat32Array): Float32Array {
  return new Float32Array(encoded.__f32);
}

export function isEncodedFloat32Array(v: unknown): v is EncodedFloat32Array {
  return typeof v === 'object' && v !== null && Array.isArray((v as EncodedFloat32Array).__f32);
}

export function encodeMap<V>(map: Map<string, V>, encodeValue?: (v: V) => unknown): EncodedMap<unknown> {
  const entries: Array<[string, unknown]> = [];
  for (const [k, v] of map.entries()) {
    entries.push([k, encodeValue ? encodeValue(v) : v]);
  }
  return { __map: entries as Array<[string, unknown]> };
}

export function decodeMap<V>(encoded: EncodedMap<unknown>, decodeValue?: (v: unknown) => V): Map<string, V> {
  const m = new Map<string, V>();
  for (const [k, v] of encoded.__map) {
    m.set(k, (decodeValue ? decodeValue(v) : v) as V);
  }
  return m;
}

export function isEncodedMap(v: unknown): v is EncodedMap<unknown> {
  return typeof v === 'object' && v !== null && Array.isArray((v as EncodedMap<unknown>).__map);
}

/**
 * Deep walk an object and encode all Float32Array/Map nodes. Useful when
 * a class's state contains nested f32 arrays in unknown locations (e.g.,
 * Trajectory.steps[i].stateEmbedding). Skip with caution — the deep walker
 * is recursive and shouldn't be used on objects with cycles.
 */
export function deepEncode(value: unknown): unknown {
  if (value instanceof Float32Array) return encodeFloat32Array(value);
  if (value instanceof Map) {
    return encodeMap(value as Map<string, unknown>, (v) => deepEncode(v));
  }
  if (Array.isArray(value)) return value.map((v) => deepEncode(v));
  if (value !== null && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) out[k] = deepEncode(v);
    return out;
  }
  return value;
}

export function deepDecode(value: unknown): unknown {
  if (isEncodedFloat32Array(value)) return decodeFloat32Array(value);
  if (isEncodedMap(value)) {
    return decodeMap(value, (v) => deepDecode(v));
  }
  if (Array.isArray(value)) return value.map((v) => deepDecode(v));
  if (value !== null && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) out[k] = deepDecode(v);
    return out;
  }
  return value;
}

